def text_or_dash(value):
    if value is None or value == "":
        return "–"
    return str(value)


def normalized_company_type_name(company_type):
    """Return one normalized company-type label for all UI/routing guards."""
    if isinstance(company_type, dict):
        raw = company_type.get("type")
    else:
        raw = company_type
    return str(raw or "").strip().lower()


def is_bank_company_type(company_type):
    return normalized_company_type_name(company_type) == "bank"


def is_insurance_company_type(company_type):
    return "versicherung" in normalized_company_type_name(company_type)


def is_reit_company_type(company_type):
    name = normalized_company_type_name(company_type)
    return "reit" in name or "immobilien" in name


def format_number(value):
    if value is None:
        return "–"

    try:
        value = float(value)

        if pd.isna(value):
            return "–"

        if abs(value) >= 1_000_000_000_000:
            return f"{value / 1_000_000_000_000:,.2f} Bio."

        if abs(value) >= 1_000_000_000:
            return f"{value / 1_000_000_000:,.2f} Mrd."

        if abs(value) >= 1_000_000:
            return f"{value / 1_000_000:,.2f} Mio."

        return f"{value:,.2f}"

    except Exception:
        return "–"


def format_money(value, currency):
    converted_value, display_currency = transform_value_for_display(value, currency)
    formatted = format_number(converted_value)

    if formatted == "–":
        return "–"

    return f"{formatted} {display_currency}"


def format_eps(value, currency):
    converted_value, display_currency = transform_value_for_display(value, currency)
    if converted_value is None:
        return "–"

    try:
        converted_value = float(converted_value)

        if pd.isna(converted_value):
            return "–"

        return f"{converted_value:,.2f} {display_currency}"

    except Exception:
        return "–"


def format_date(timestamp):
    if timestamp is None:
        return None

    try:
        date_value = datetime.fromtimestamp(timestamp)

        if date_value.date() < datetime.now().date():
            return None

        return date_value.strftime("%d.%m.%Y")

    except Exception:
        return None


def safe_float(value):
    try:
        value = float(value)

        if pd.isna(value):
            return None

        return value

    except Exception:
        return None


DISPLAY_CURRENCY_SESSION_KEY = "_v22048_display_currency_context"


def _normalize_currency_code(code):
    raw = str(code or "").strip()
    if raw.upper() == "GBX":
        return "GBp"
    return raw


def set_display_currency_context(context):
    """Store presentation-only FX context. Valuation inputs remain untouched."""
    try:
        st.session_state[DISPLAY_CURRENCY_SESSION_KEY] = dict(context or {})
    except Exception:
        pass


def get_display_currency_context():
    try:
        value = st.session_state.get(DISPLAY_CURRENCY_SESSION_KEY, {})
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def transform_value_for_display(value, source_currency):
    """Convert one monetary display value without changing model calculations."""
    numeric = safe_float(value)
    source = _normalize_currency_code(source_currency)
    if numeric is None:
        return None, source or text_or_dash(source_currency)

    context = get_display_currency_context()
    if not context.get("enabled"):
        return numeric, source or text_or_dash(source_currency)

    target = _normalize_currency_code(context.get("target_currency"))
    rates = context.get("rates") if isinstance(context.get("rates"), dict) else {}
    rate_info = rates.get(source) if source else None

    # Lazy-load additional source currencies used by specialist modules (for
    # example hard-coded USD/oz mining primary-source values) without making
    # every stock load fetch all possible FX pairs up front.
    if (
        source
        and target
        and source != target
        and not isinstance(rate_info, dict)
        and context.get("cache_version")
    ):
        try:
            rate_info = load_fx_conversion(source, target, context.get("cache_version"))
            context.setdefault("rates", {})[source] = rate_info
            set_display_currency_context(context)
        except Exception:
            rate_info = None

    factor = safe_float((rate_info or {}).get("factor")) if isinstance(rate_info, dict) else None

    if source == target:
        factor = 1.0

    if not target or factor is None or factor <= 0:
        return numeric, source or text_or_dash(source_currency)

    return numeric * factor, target


def format_currency_value(value, currency, decimals=2, signed=False):
    converted_value, display_currency = transform_value_for_display(value, currency)
    if converted_value is None:
        return "–"
    sign = "+" if signed else ""
    return f"{converted_value:{sign},.{int(decimals)}f} {display_currency}"


def format_currency_range(low, high, currency, decimals=2):
    low_value, low_currency = transform_value_for_display(low, currency)
    high_value, high_currency = transform_value_for_display(high, currency)
    if low_value is None or high_value is None:
        return "–"
    display_currency = high_currency if high_currency == low_currency else low_currency
    return f"{low_value:,.{int(decimals)}f} – {high_value:,.{int(decimals)}f} {display_currency}"


def format_currency_per_unit(value, currency, unit_suffix, decimals=2, signed=False):
    converted_value, display_currency = transform_value_for_display(value, currency)
    if converted_value is None:
        return "–"
    sign = "+" if signed else ""
    suffix = str(unit_suffix or "").strip()
    return f"{converted_value:{sign},.{int(decimals)}f} {display_currency}/{suffix}"


def format_musd(value_musd, decimals=2):
    value = safe_float(value_musd)
    if value is None:
        return "–"
    return format_money(value * 1_000_000.0, "USD")


def format_source_unit_value(value, unit_label, decimals=2, signed=False):
    unit = str(unit_label or "").strip()
    if "/" in unit:
        prefix, suffix = unit.split("/", 1)
        prefix = _normalize_currency_code(prefix)
        if prefix in {"USD", "EUR", "GBP", "GBp", "CHF", "JPY", "CAD", "AUD", "SEK", "NOK", "DKK"}:
            return format_currency_per_unit(value, prefix, suffix, decimals, signed=signed)
    normalized = _normalize_currency_code(unit)
    if normalized in {"USD", "EUR", "GBP", "GBp", "CHF", "JPY", "CAD", "AUD", "SEK", "NOK", "DKK"}:
        return format_currency_value(value, normalized, decimals, signed=signed)
    numeric = safe_float(value)
    if numeric is None:
        return "–"
    sign = "+" if signed else ""
    return f"{numeric:{sign},.{int(decimals)}f} {unit}".strip()


def format_source_unit_range(low, high, unit_label, decimals=2):
    unit = str(unit_label or "").strip()
    if "/" in unit:
        prefix, suffix = unit.split("/", 1)
        prefix = _normalize_currency_code(prefix)
        if prefix in {"USD", "EUR", "GBP", "GBp", "CHF", "JPY", "CAD", "AUD", "SEK", "NOK", "DKK"}:
            low_text = format_currency_per_unit(low, prefix, suffix, decimals)
            high_value, high_currency = transform_value_for_display(high, prefix)
            low_value, low_currency = transform_value_for_display(low, prefix)
            if low_value is None or high_value is None:
                return "–"
            shown_currency = high_currency if high_currency == low_currency else low_currency
            return f"{low_value:,.{int(decimals)}f} – {high_value:,.{int(decimals)}f} {shown_currency}/{suffix}"
    low_value = safe_float(low)
    high_value = safe_float(high)
    if low_value is None or high_value is None:
        return "–"
    return f"{low_value:,.{int(decimals)}f} – {high_value:,.{int(decimals)}f} {unit}".strip()


def display_currency_code(source_currency):
    """Return the currently shown currency code for labels around monetary values."""
    source = _normalize_currency_code(source_currency)
    context = get_display_currency_context()
    if context.get("enabled") and context.get("target_currency"):
        rate_info = (context.get("rates") or {}).get(source)
        if source == context.get("target_currency") or (isinstance(rate_info, dict) and safe_float(rate_info.get("factor"))):
            return context.get("target_currency")
    return source or text_or_dash(source_currency)


def build_currency_context(
    quote_currency,
    financial_currency=None,
    fx_conversion=None
):
    """
    Keep trading/quote currency separate from the currency of fundamentals.

    Examples:
    - UK shares can trade in GBp while fundamentals are in GBP.
    - A German secondary listing can trade in EUR while the verified primary
      fundamental source reports in USD. In that case an explicit FX factor
      is required for Fair-Value/price comparisons.

    No currency mismatch is silently treated as 1:1.
    """
    raw_quote = str(quote_currency or "").strip()
    raw_financial = str(
        financial_currency or raw_quote or ""
    ).strip()

    if raw_quote.upper() == "GBX":
        raw_quote = "GBp"

    if raw_financial.upper() == "GBX":
        raw_financial = "GBp"

    # Explicit UK pence handling.
    if raw_quote == "GBp" and raw_financial == "GBP":
        return {
            "quote_currency": "GBp",
            "financial_currency": "GBP",
            "valuation_currency": "GBP",
            "mixed_units": True,
            "conversion_available": True,
            "conversion_kind": "gbp_pence",
            "financial_to_quote_factor": 100.0,
            "quote_to_financial_factor": 0.01,
            "fx_symbol": None,
            "note": (
                "Britische Pence-Notierung erkannt: Der Aktienkurs wird "
                "in GBp (Pence) geführt, während EPS und die fundamentalen "
                "Finanzkennzahlen in GBP (Pfund Sterling) geführt werden. "
                "Für den Fair-Value/Kurs-Vergleich wird ausdrücklich "
                "1 GBP = 100 GBp verwendet."
            )
        }

    # Same currency: no conversion required.
    if raw_quote and raw_financial and raw_quote == raw_financial:
        return {
            "quote_currency": raw_quote,
            "financial_currency": raw_financial,
            "valuation_currency": raw_financial,
            "mixed_units": False,
            "conversion_available": True,
            "conversion_kind": "same_currency",
            "financial_to_quote_factor": 1.0,
            "quote_to_financial_factor": 1.0,
            "fx_symbol": None,
            "note": None
        }

    fx = fx_conversion if isinstance(fx_conversion, dict) else {}
    factor = safe_float(fx.get("factor"))

    if (
        raw_quote
        and raw_financial
        and factor is not None
        and factor > 0
    ):
        inverse = 1.0 / factor
        fx_symbol = fx.get("symbol")

        return {
            "quote_currency": raw_quote,
            "financial_currency": raw_financial,
            "valuation_currency": raw_financial,
            "mixed_units": True,
            "conversion_available": True,
            "conversion_kind": "fx",
            "financial_to_quote_factor": factor,
            "quote_to_financial_factor": inverse,
            "fx_symbol": fx_symbol,
            "note": (
                f"Getrennte Handels- und Finanzwährung erkannt: Kurs in "
                f"{raw_quote}, Fundamentaldaten in {raw_financial}. Für "
                f"Bewertungen wird ausdrücklich 1 {raw_financial} = "
                f"{factor:.6f} {raw_quote} verwendet"
                + (f" ({fx_symbol})." if fx_symbol else ".")
            )
        }

    # Mismatch without a verified conversion: keep it visible and block
    # currency-dependent valuation steps instead of assuming parity.
    return {
        "quote_currency": raw_quote or quote_currency,
        "financial_currency": raw_financial or financial_currency,
        "valuation_currency": raw_financial or financial_currency,
        "mixed_units": bool(raw_quote and raw_financial and raw_quote != raw_financial),
        "conversion_available": False,
        "conversion_kind": "unavailable",
        "financial_to_quote_factor": None,
        "quote_to_financial_factor": None,
        "fx_symbol": None,
        "note": (
            "Kurs- und Finanzwährung weichen voneinander ab. Eine belastbare "
            "Währungsumrechnung konnte nicht geladen werden; abhängige "
            "Bewertungsschritte werden deshalb gesperrt."
        ) if raw_quote != raw_financial else None
    }


def validate_valuation_currency_context(currency_context):
    """Fail-closed currency gate for every Fair-Value/price comparison.

    A valuation may continue only when trading and financial currencies are
    explicit and either identical or connected by a positive, verified
    conversion factor. This gate is independent of the presentation currency.
    """
    context = currency_context if isinstance(currency_context, dict) else {}
    quote_currency = str(context.get("quote_currency") or "").strip()
    financial_currency = str(context.get("financial_currency") or "").strip()

    if not quote_currency or not financial_currency:
        return {
            "passed": False,
            "note": (
                "Currency-Sanity-Check nicht bestanden: Handels- und Berichtswährung "
                "sind nicht beide eindeutig verfügbar. Fair Value bleibt gesperrt."
            ),
        }

    mixed = bool(context.get("mixed_units")) or quote_currency != financial_currency
    if not mixed:
        return {
            "passed": True,
            "note": f"Currency-Sanity-Check bestanden: Handels- und Berichtswährung sind {quote_currency}.",
        }

    factor = safe_float(context.get("financial_to_quote_factor"))
    if not context.get("conversion_available") or factor is None or factor <= 0:
        return {
            "passed": False,
            "note": (
                f"Currency-Sanity-Check nicht bestanden: Fundamentaldaten in {financial_currency} "
                f"und Handelskurs in {quote_currency}, aber kein positiver verifizierter FX-/Einheitenfaktor. "
                "Fair Value bleibt gesperrt; es wird niemals 1:1 angenommen."
            ),
        }

    return {
        "passed": True,
        "note": (
            f"Currency-Sanity-Check bestanden: Fundamentaldaten {financial_currency} → "
            f"Handelswährung {quote_currency} mit Faktor {factor:.6f}."
        ),
    }


