VERIFIED_SHARE_UNIT_ROUTES = {
    # Toyota Motor Corporation 2026 Form 20-F:
    # NYSE ticker TM is an American Depositary Share (ADS), and each ADS
    # represents ten Toyota common shares. Fundamentals are therefore routed
    # to the Tokyo primary listing so current and historical per-share values
    # use the same ordinary-share unit.
    "TM": {
        "fundamental_symbol": "7203.T",
        "quote_unit_name": "Toyota ADS / ADR",
        "fundamental_unit_name": "Toyota-Stammaktie",
        "fundamental_shares_per_quote_unit": 10.0,
        "source_name": "Toyota Motor Corporation – Form 20-F 2026",
        "source_url": "https://www.sec.gov/Archives/edgar/data/1094517/000119312526264811/d101983d20f.htm",
        "source_note": (
            "Verifiziertes Verhältnis: 1 Toyota ADS/ADR (TM) repräsentiert "
            "10 Toyota-Stammaktien."
        ),
    },
}


def build_share_unit_context(selected_symbol, fundamental_symbol, route=None):
    """Return only explicitly verified per-share unit conversions.

    Unknown ADR/depositary-receipt ratios are never inferred from price,
    market cap, EPS or FX. If a listing is not present in the verified map,
    the normal one-share-to-one-share assumption remains in force only when
    no separate share-unit route has been declared.
    """
    selected = str(selected_symbol or "").strip().upper()
    fundamental = str(fundamental_symbol or "").strip().upper()
    route_info = route if isinstance(route, dict) else {}
    verified = VERIFIED_SHARE_UNIT_ROUTES.get(selected)

    if not isinstance(verified, dict):
        return {
            "applicable": False,
            "conversion_required": False,
            "conversion_available": True,
            "fundamental_shares_per_quote_unit": 1.0,
            "quote_unit_name": "Aktie",
            "fundamental_unit_name": "Aktie",
            "source_name": None,
            "source_url": None,
            "note": None,
        }

    expected_fundamental = str(
        verified.get("fundamental_symbol") or ""
    ).strip().upper()
    ratio = safe_float(
        verified.get("fundamental_shares_per_quote_unit")
    )
    route_matches = bool(
        fundamental
        and expected_fundamental
        and fundamental == expected_fundamental
    )
    ratio_valid = ratio is not None and ratio > 0
    available = (
        route_matches
        and ratio_valid
        and not route_info.get("primary_source_unavailable")
    )

    note = verified.get("source_note")
    if available:
        note = (
            f"ADR-/Aktieneinheit verifiziert: {note} Der Börsenkurs bleibt "
            f"in der Einheit {selected}; Fundamentaldaten und historische "
            f"EPS werden dagegen aus {fundamental} je "
            f"{verified.get('fundamental_unit_name', 'Stammaktie')} geladen. "
            "Bei einem späteren Kurs/Fair-Value-Vergleich werden sowohl "
            "Währung als auch das verifizierte Aktienverhältnis ausdrücklich "
            "umgerechnet."
        )
    else:
        note = (
            "ADR-/Aktieneinheiten-Gate aktiv, aber die verifizierte "
            "Primärnotierung bzw. das bestätigte Aktienverhältnis steht "
            "nicht konsistent zur Verfügung. Per-Share-basierte "
            "Bewertungsschritte müssen deshalb gesperrt bleiben."
        )

    return {
        "applicable": True,
        "conversion_required": True,
        "conversion_available": available,
        "fundamental_shares_per_quote_unit": ratio if ratio_valid else None,
        "quote_unit_name": verified.get("quote_unit_name"),
        "fundamental_unit_name": verified.get("fundamental_unit_name"),
        "source_name": verified.get("source_name"),
        "source_url": verified.get("source_url"),
        "expected_fundamental_symbol": expected_fundamental,
        "route_reason": route_info.get("reason"),
        "note": note,
    }


def convert_quote_price_to_financial_share_unit(price, currency_context):
    """Convert quote price to the fundamental per-share unit, fail closed."""
    quote_price = safe_float(price)
    if quote_price is None:
        return None

    context = currency_context if isinstance(currency_context, dict) else {}
    quote_to_financial = safe_float(
        context.get("quote_to_financial_factor", 1.0)
    )
    if quote_to_financial is None or quote_to_financial <= 0:
        return None

    share_context = context.get("share_unit_context") or {}
    ratio = 1.0
    if share_context.get("conversion_required"):
        if not share_context.get("conversion_available"):
            return None
        ratio = safe_float(
            share_context.get("fundamental_shares_per_quote_unit")
        )
        if ratio is None or ratio <= 0:
            return None

    # Example Toyota TM: USD per ADR -> JPY per ADR via FX -> divide by
    # 10 common shares represented by one ADR -> JPY per common share.
    return quote_price * quote_to_financial / ratio


def sanitize_profit_margin(
    raw_margin,
    net_income,
    revenue
):
    """
    Treat a demonstrably contradictory Yahoo 0.0 margin as missing.

    A real zero remains valid when the reported net income is also zero.
    No replacement margin is estimated from other values.
    """
    margin = safe_float(raw_margin)
    net_income_value = safe_float(net_income)
    revenue_value = safe_float(revenue)

    if margin is None:
        return None, None

    if (
        margin == 0.0
        and revenue_value is not None
        and revenue_value > 0
        and net_income_value is not None
        and net_income_value != 0.0
    ):
        return (
            None,
            (
                "Yahoo meldet 0,0 % Nettomarge, obwohl gleichzeitig "
                "ein von null abweichender Nettogewinn ausgewiesen wird. "
                "Der widersprüchliche Margenwert wird deshalb als fehlend "
                "behandelt und erhält keine Punkte."
            )
        )

    return margin, None


def apply_eps_confidence_brake(
    base_confidence,
    trailing_eps,
    forward_eps
):
    """
    Reduce EPS-normalization confidence when positive TTM and forward EPS
    diverge strongly. Weight changes are handled separately by the
    V2.20.1 EPS-Divergence Gate.
    """
    trailing = safe_float(trailing_eps)
    forward = safe_float(forward_eps)

    if (
        trailing is None
        or forward is None
        or trailing <= 0
        or forward <= 0
    ):
        return base_confidence, None, None

    deviation = abs(forward / trailing - 1.0)

    confidence_rank = {
        "Niedrig": 0,
        "Mittel": 1,
        "Hoch": 2
    }

    if deviation >= 1.50:
        confidence_cap = "Niedrig"
    elif deviation >= 0.50:
        confidence_cap = "Mittel"
    else:
        return base_confidence, None, deviation

    base_rank = confidence_rank.get(
        base_confidence,
        0
    )
    cap_rank = confidence_rank[
        confidence_cap
    ]

    confidence = (
        base_confidence
        if base_rank <= cap_rank
        else confidence_cap
    )

    note = (
        "TTM-EPS und Forward-EPS weichen um "
        f"{deviation * 100:.1f} % voneinander ab. "
        f"Die angezeigte Sicherheit wird höchstens als {confidence_cap} eingestuft."
    )

    return confidence, note, deviation


def apply_eps_divergence_gate(
    base_trailing_weight,
    base_forward_weight,
    trailing_eps,
    forward_eps
):
    """
    V2.20.1 – EPS-Divergence Gate for non-cyclical EPS normalization.

    The normal growth-based weighting remains valid while TTM and forward EPS
    are close. With larger positive-EPS divergence the model automatically
    reduces reliance on the forward estimate:

    - deviation <= 25 %: keep the normal base weighting
    - >25 % to 50 %: 50 % TTM / 50 % Forward
    - >50 % to 100 %: 60 % TTM / 40 % Forward
    - >100 %: 70 % TTM / 30 % Forward

    No estimate is invented when one EPS value is missing or non-positive.
    """
    trailing = safe_float(trailing_eps)
    forward = safe_float(forward_eps)

    if (
        trailing is None
        or forward is None
        or trailing <= 0
        or forward <= 0
    ):
        return {
            "trailing_weight": base_trailing_weight,
            "forward_weight": base_forward_weight,
            "deviation": None,
            "active": False,
            "band": None,
            "note": None
        }

    deviation = abs(forward / trailing - 1.0)

    if deviation <= 0.25:
        return {
            "trailing_weight": base_trailing_weight,
            "forward_weight": base_forward_weight,
            "deviation": deviation,
            "active": False,
            "band": "bis 25 %",
            "note": None
        }

    if deviation <= 0.50:
        trailing_weight = 0.50
        forward_weight = 0.50
        band = ">25 % bis 50 %"
    elif deviation <= 1.00:
        trailing_weight = 0.60
        forward_weight = 0.40
        band = ">50 % bis 100 %"
    else:
        trailing_weight = 0.70
        forward_weight = 0.30
        band = ">100 %"

    note = (
        "EPS-Divergenz-Gate aktiv: TTM-EPS und Forward-EPS weichen um "
        f"{deviation * 100:.1f} % voneinander ab. Deshalb wird die "
        f"Gewichtung auf {trailing_weight * 100:.0f} % TTM-EPS und "
        f"{forward_weight * 100:.0f} % Forward-EPS begrenzt."
    )

    return {
        "trailing_weight": trailing_weight,
        "forward_weight": forward_weight,
        "deviation": deviation,
        "active": True,
        "band": band,
        "note": note
    }


def evaluate_cycle_eps_comparability_gate(
    company_type,
    cycle_basis,
    trailing_eps,
    forward_eps
):
    """
    V2.20.10 – Comparability gate for cyclical auto suppliers.

    A historical cycle EPS can become misleading after major one-offs or
    structural changes. For auto suppliers, block KGV/Fair-Value use when
    BOTH of the following are true:

    - Forward EPS differs by more than 100 % from the historical cycle basis.
    - TTM and Forward EPS differ by at least 150 %.

    The already calculated normalized EPS remains visible as a diagnostic
    value, but it is not released as a valuation basis. No adjusted earnings
    are invented.
    """
    type_name = str((company_type or {}).get("type", "")).lower()

    if "autozulieferer" not in type_name:
        return {
            "active": False,
            "blocked": False,
            "cycle_forward_deviation": None,
            "ttm_forward_deviation": None,
            "note": None,
        }

    cycle = safe_float(cycle_basis)
    trailing = safe_float(trailing_eps)
    forward = safe_float(forward_eps)

    if (
        cycle is None
        or trailing is None
        or forward is None
        or cycle <= 0
        or trailing <= 0
        or forward <= 0
    ):
        return {
            "active": False,
            "blocked": False,
            "cycle_forward_deviation": None,
            "ttm_forward_deviation": None,
            "note": None,
        }

    cycle_forward_deviation = abs(forward / cycle - 1.0)
    ttm_forward_deviation = abs(forward / trailing - 1.0)

    blocked = (
        cycle_forward_deviation > 1.00
        and ttm_forward_deviation >= 1.50
    )

    if not blocked:
        return {
            "active": False,
            "blocked": False,
            "cycle_forward_deviation": cycle_forward_deviation,
            "ttm_forward_deviation": ttm_forward_deviation,
            "note": None,
        }

    note = (
        "Zyklus-EPS-Vergleichbarkeits-Gate aktiv: Forward-EPS und historische "
        f"Zyklus-Basis weichen um {cycle_forward_deviation * 100:.1f} % voneinander ab; "
        f"TTM-EPS und Forward-EPS um {ttm_forward_deviation * 100:.1f} %. "
        "Die historische EPS-Basis kann durch Sondereffekte oder Strukturänderungen "
        "verzerrt sein. Der berechnete normalisierte EPS-Wert bleibt nur ein "
        "Diagnosewert; KGV-Multiple und Fair Value werden bis zur "
        "Vergleichbarkeitsprüfung gesperrt."
    )

    return {
        "active": True,
        "blocked": True,
        "cycle_forward_deviation": cycle_forward_deviation,
        "ttm_forward_deviation": ttm_forward_deviation,
        "note": note,
    }



def build_special_event_warning(eps_normalization, bank_special_model=None, insurance_special_model=None):
    """
    V2.20.35 – Sonderereignis-Warnampel mit Bank-Sonderposten-Integration.

    Die Ampel übersetzt technische EPS-/Vergleichbarkeits-Signale in eine
    einfache Handlungsebene:

    - Grün: keine wesentliche Sonderauffälligkeit aus der EPS-Prüfung.
    - Gelb: auffällige Abweichung oder verifizierter bankspezifischer
      Sonderposten; Bewertung bleibt auf dieser Ampel-Ebene nutzbar,
      eine bereits offiziell bereinigte Bank-Kennzahl braucht keine
      zusätzliche Sonderrecherche.
    - Rot: Bewertungsbasis ist nicht ausreichend vergleichbar; Fair Value
      bleibt gesperrt und eine gezielte Geschäftsbericht-/IR-/Internetprüfung
      ist erforderlich, bevor die Bewertung wieder freigegeben werden darf.

    Es werden keine Ursachen erfunden. Die Ampel sagt nur, *dass* eine
    Sonderprüfung nötig ist, nicht *warum* die Abweichung entstanden ist.
    """
    eps = eps_normalization if isinstance(eps_normalization, dict) else {}

    comparability_blocked = bool(
        eps.get("cycle_eps_comparability_blocked")
        or eps.get("normalization_blocked_by_structural_break")
        or eps.get("valuation_blocked")
    )

    if comparability_blocked:
        reasons = []
        if eps.get("cycle_eps_comparability_blocked"):
            reasons.append(
                "historische Zyklus-Basis und aktuelle/erwartete Gewinne sind nicht ausreichend vergleichbar"
            )
        if eps.get("normalization_blocked_by_structural_break"):
            reasons.append(
                "nach einem bestätigten Strukturbruch liegen noch zu wenige vollständig vergleichbare Jahre vor"
            )

        reason_text = "; ".join(reasons) or (
            "die EPS-Bewertungsbasis ist für einen belastbaren Fair Value nicht freigegeben"
        )

        return {
            "level": "Rot",
            "icon": "🔴",
            "title": "Sonderprüfung erforderlich",
            "requires_research": True,
            "valuation_usable": False,
            "reason": reason_text + ".",
            "action": (
                "Gezielt Geschäftsbericht, Investor-Relations-Mitteilungen und seriöse aktuelle Quellen "
                "auf mögliche Sondereffekte oder Strukturänderungen prüfen (z. B. Abspaltung, Übernahme, "
                "Verkauf, Restrukturierung, Impairment/Abschreibung oder außergewöhnliche Einmalposten). "
                "Bis die Ursache und Vergleichbarkeit geklärt sind, bleibt der Fair Value gesperrt."
            ),
        }

    ttm_forward_deviation = safe_float(eps.get("ttm_forward_deviation"))
    cycle_forward_deviation = safe_float(eps.get("cycle_forward_deviation"))
    structural_break_active = bool(eps.get("structural_break_active"))
    eps_divergence_active = bool(eps.get("eps_divergence_note"))

    yellow_reasons = []
    if structural_break_active:
        yellow_reasons.append("bestätigte Strukturänderung wird bereits berücksichtigt")
    if ttm_forward_deviation is not None and ttm_forward_deviation >= 0.50:
        yellow_reasons.append(
            f"TTM- und Forward-EPS weichen um {ttm_forward_deviation * 100:.1f} % voneinander ab"
        )
    elif eps_divergence_active:
        yellow_reasons.append("starke TTM-/Forward-EPS-Abweichung wurde erkannt")
    if cycle_forward_deviation is not None and cycle_forward_deviation >= 0.50:
        yellow_reasons.append(
            f"Forward-EPS und Zyklus-Basis weichen um {cycle_forward_deviation * 100:.1f} % voneinander ab"
        )

    bank_model = (
        bank_special_model
        if isinstance(bank_special_model, dict)
        else {}
    )
    bank_snapshot = bank_model.get("snapshot") or {}
    bank_significant_eps = safe_float(
        bank_snapshot.get("significant_items_eps_effect")
    )
    bank_rote_reported = safe_float(
        bank_model.get("rote_reported_pct")
    )
    bank_rote_normalized = safe_float(
        bank_model.get("rote_normalized_pct")
    )
    bank_special_items_verified = bool(
        bank_model.get("applicable")
        and bank_model.get("primary_source_complete")
        and bank_model.get("snapshot_fresh")
        and bank_significant_eps is not None
        and abs(bank_significant_eps) > 1e-12
        and bank_rote_normalized is not None
    )

    if bank_special_items_verified:
        bank_reason = (
            "Die verifizierte Bank-Primärquelle weist wesentliche Sonderposten "
            f"mit einem EPS-Effekt von {bank_significant_eps:+.2f} aus. "
            "Für die Ertragsqualitätsprüfung wird deshalb der offiziell "
            f"bereinigte ROTCE von {bank_rote_normalized:.1f} % als "
            "normalisierte Ertragskraft geführt"
        )
        if bank_rote_reported is not None:
            bank_reason += (
                f"; der gemeldete ROTCE von {bank_rote_reported:.1f} % "
                "bleibt separat sichtbar"
            )
        if yellow_reasons:
            bank_reason += ". Zusätzlich: " + "; ".join(yellow_reasons)
        bank_reason += "."

        return {
            "level": "Gelb",
            "icon": "🟡",
            "title": "Sonderposten erkannt, bankspezifisch bereinigt",
            "requires_research": False,
            "valuation_usable": True,
            "reason": bank_reason,
            "action": (
                "Keine zusätzliche Sonderrecherche erforderlich: Die aktuelle "
                "verifizierte Bank-Primärquelle enthält bereits eine offizielle "
                "Bereinigung. Die Freigabe eines Bank-Fair-Values bleibt davon "
                "getrennt und richtet sich weiterhin ausschließlich nach dem "
                "Bank-Sondermodell."
            ),
        }


    insurance_model = (
        insurance_special_model
        if isinstance(insurance_special_model, dict)
        else {}
    )
    insurance_snapshot = insurance_model.get("snapshot") or {}
    headline_core_eps_growth = safe_float(
        insurance_model.get("core_eps_growth_pct")
    )
    underlying_core_eps_growth = safe_float(
        insurance_model.get("underlying_core_eps_growth_pct")
    )
    insurance_effects_verified = bool(
        insurance_model.get("applicable")
        and insurance_model.get("primary_source_complete")
        and insurance_model.get("snapshot_fresh")
        and headline_core_eps_growth is not None
        and underlying_core_eps_growth is not None
        and abs(headline_core_eps_growth - underlying_core_eps_growth) >= 3.0
    )

    if insurance_effects_verified:
        return {
            "level": "Gelb",
            "icon": "🟡",
            "title": "Transaktions-/Divestment-Effekte erkannt – Versicherungswachstum bereinigt",
            "requires_research": False,
            "valuation_usable": True,
            "reason": (
                "Die verifizierte Versicherungs-Primärquelle weist für 6M 2026 "
                f"ein Core-EPS-Wachstum von {headline_core_eps_growth:.1f} % aus, "
                f"nennt nach Transaktions-/Divestment-Effekten aber ein underlying "
                f"Wachstum von {underlying_core_eps_growth:.1f} %. Für den "
                "Versicherungs-Score wird deshalb der offiziell ausgewiesene "
                "underlying-Wert verwendet. Ein künstlich bereinigtes absolutes "
                "Core EPS wird nicht erzeugt."
            ),
            "action": (
                "Keine zusätzliche Sonderrecherche erforderlich: Die aktuelle Allianz-"
                "Primärquelle benennt die Effekte und liefert bereits die underlying "
                "Wachstums-/RoE-Kennzahlen. Die spätere Fair-Value-Freigabe bleibt "
                "davon getrennt und richtet sich ausschließlich nach dem "
                "Versicherungs-Sondermodell."
            ),
        }

    if yellow_reasons:
        return {
            "level": "Gelb",
            "icon": "🟡",
            "title": "Auffälligkeit erkannt – Bewertung weiter nutzbar",
            "requires_research": False,
            "valuation_usable": True,
            "reason": "; ".join(yellow_reasons) + ".",
            "action": (
                "Die App hat die Unsicherheit bereits konservativ berücksichtigt. Eine Sonderrecherche ist "
                "nicht zwingend, solange kein rotes Gate ausgelöst wird; die Bewertung sollte aber mit der "
                "angezeigten Sicherheitsstufe verwendet werden."
            ),
        }

    return {
        "level": "Grün",
        "icon": "🟢",
        "title": "Keine wesentliche Sonderauffälligkeit erkannt",
        "requires_research": False,
        "valuation_usable": True,
        "reason": "Die EPS-/Vergleichbarkeitsprüfung zeigt derzeit keinen materiellen Sonderfall.",
        "action": "Normale Bewertungslogik kann ohne zusätzliche Sonderrecherche weiterlaufen.",
    }


# =========================================================
# V2.20.14 – Primärquellen-Recovery für Sonderereignisse
# =========================================================

SPECIAL_EVENT_KEYWORDS = {
    "Abspaltung / Spin-off": [
        "spin-off", "spinoff", "spin off", "separation", "demerger",
        "abspaltung", "abgespalten",
    ],
    "Restrukturierung": [
        "restructuring", "restructure", "restructur", "reorganization",
        "reorganisation", "cost reduction", "cost-reduction",
        "restrukturierung", "restruktur",
    ],
    "Impairment / Abschreibung": [
        "impairment", "write-down", "writedown", "write off", "write-off",
        "non-cash charge", "noncash charge", "abschreibung", "wertminderung",
    ],
    "Übernahme / Akquisition": [
        "acquisition", "acquire", "acquired", "merger", "business combination",
        "übernahme", "akquisition", "fusion",
    ],
    "Verkauf / Desinvestition": [
        "divestiture", "divestment", "disposed", "disposal", "sale of business",
        "discontinued operations", "verkauf", "desinvestition",
    ],
    "Einmal-/Sonderposten": [
        "one-time", "one time", "non-recurring", "nonrecurring", "special charge",
        "exceptional item", "adjusted eps", "adjusted earnings", "adjusted net income",
        "reported eps", "gaap eps", "non-comparable", "noncomparable",
        "sonderposten", "einmaleffekt",
    ],
    "Steuer-/Rechtseffekt": [
        "tax benefit", "tax charge", "tax settlement", "litigation", "legal settlement",
        "steuerertrag", "steueraufwand", "rechtsstreit", "vergleichszahlung",
    ],
}

TRUSTED_SECONDARY_DOMAINS = {
    "reuters.com", "apnews.com", "bloomberg.com", "wsj.com", "ft.com",
    "marketwatch.com", "morningstar.com", "finance.yahoo.com",
}

PRIMARY_PATH_HINTS = [
    "/investors", "/investor-relations", "/investorrelations",
    "/newsroom", "/news", "/press-releases", "/press", "/media",
    "/investors/news", "/investors/news-and-events", "/investors/news-events",
    "/investors/financials", "/investors/quarterly-results",
]

PRIMARY_LINK_KEYWORDS = [
    "results", "earnings", "quarter", "annual", "guidance", "financial",
    "10-k", "10q", "10-q", "8-k", "press-release", "press release",
    "investor", "impairment", "restructuring", "spin-off", "spinoff",
    "separation", "divest", "adjusted eps", "non-comparable",
]

SEC_FORMS = {"10-K", "10-Q", "8-K"}


def _clean_text(value):
    return re.sub(r"\s+", " ", str(value or "")).strip()


def _extract_company_domain(website):
    raw = _clean_text(website)
    if not raw:
        return None
    try:
        parsed = urlparse(raw if "://" in raw else "https://" + raw)
        host = (parsed.netloc or "").lower().split(":")[0]
        if host.startswith("www."):
            host = host[4:]
        return host or None
    except Exception:
        return None


def _normalize_host(url):
    try:
        host = (urlparse(url).netloc or "").lower().split(":")[0]
        return host[4:] if host.startswith("www.") else host
    except Exception:
        return ""


def _source_category(url, company_domain=None):
    host = _normalize_host(url)
    if host == "sec.gov" or host.endswith(".sec.gov"):
        return "Regulatorisch / SEC", True
    if company_domain and (host == company_domain or host.endswith("." + company_domain)):
        return "Unternehmen / Investor Relations", True
    if any(host == d or host.endswith("." + d) for d in TRUSTED_SECONDARY_DOMAINS):
        return "Seriöse Sekundärquelle", False
    return "Weitere Webquelle", False


def _classify_special_event_text(text):
    """Broad keyword scan used only for discovery. Final evidence uses the stricter validator below."""
    haystack = _clean_text(text).lower()
    labels = []
    for label, keywords in SPECIAL_EVENT_KEYWORDS.items():
        if any(keyword in haystack for keyword in keywords):
            labels.append(label)
    return labels


def _context_looks_like_actual_event(context, label):
    """
    Reject pure non-GAAP definition boilerplate. A displayed cause needs either an
    actual action/charge or a quantitative/time-specific context.
    """
    c = _clean_text(context).lower()
    if not c:
        return False

    definition_only = any(x in c for x in [
        "defines adjusted", "defined as", "definition of", "adjusted to eliminate",
        "may include", "can include", "non-gaap measures", "non-gaap measure",
        "for comparison with", "most directly comparable", "we believe the following table",
    ])

    action_cues = [
        "recorded", "recognized", "incurred", "completed", "completion", "announced",
        "acquired", "acquisition of", "sold", "sale of", "divested", "divestiture of",
        "spun off", "spin-off of", "separated", "separation of", "restructuring expense",
        "restructuring charge", "impairment charge", "impairment charges", "write-down",
        "write off", "write-off", "tax charge", "tax benefit", "settlement", "non-comparable items",
        "noncomparable items", "net losses per diluted share", "net gains per diluted share",
    ]
    has_action = any(x in c for x in action_cues)
    has_money = bool(re.search(r"(?:\$|€|£)\s*\(?-?\d", c))
    has_period = bool(re.search(
        r"\b(?:20\d{2}|q[1-4]\s*20\d{2}|first quarter|second quarter|third quarter|fourth quarter|full[-\s]?year|fiscal year)\b",
        c,
        flags=re.I,
    ))

    # Generic adjusted-EPS wording alone is not an event.
    if label == "Einmal-/Sonderposten":
        concrete_special = any(x in c for x in [
            "non-comparable items", "noncomparable items", "one-time charge", "one time charge",
            "special charge", "exceptional item", "excluded net non-comparable", "excluded net noncomparable",
        ])
        if not concrete_special and not (has_action and has_money):
            return False

    if definition_only and not (has_action and (has_money or has_period)):
        return False

    return bool(has_action or (has_money and has_period))


def _classify_special_event_evidence(text):
    """Stricter event classifier for user-visible evidence."""
    haystack = _clean_text(text).lower()
    labels = []
    for label, keywords in SPECIAL_EVENT_KEYWORDS.items():
        matched = False
        for keyword in keywords:
            for m in re.finditer(re.escape(keyword), haystack, flags=re.I):
                left = max(0, m.start() - 260)
                right = min(len(haystack), m.end() + 320)
                if _context_looks_like_actual_event(haystack[left:right], label):
                    matched = True
                    break
            if matched:
                break
        if matched:
            labels.append(label)
    return labels


def _company_identity_tokens(company_name):
    raw = _clean_text(company_name).lower()
    raw = re.sub(r"[^a-z0-9äöüß]+", " ", raw)
    stop = {
        "inc", "incorporated", "corp", "corporation", "company", "co", "ltd", "limited",
        "plc", "ag", "sa", "se", "nv", "holdings", "holding", "group", "the",
    }
    tokens = []
    for token in raw.split():
        if token in stop:
            continue
        if len(token) >= 4 or any(ch.isdigit() for ch in token):
            tokens.append(token)
    compact = re.sub(r"[^a-z0-9äöüß]+", "", raw)
    if compact and compact not in stop and len(compact) >= 4:
        tokens.append(compact)
    return list(dict.fromkeys(tokens))


def _source_matches_company(item, page_text, company_name, symbol, company_domain, primary):
    """
    Primary company-domain and SEC rows are trusted by construction. Other web
    rows must actually mention the analyzed company, so unrelated search hits
    (e.g. another issuer's press release) cannot enter the evidence list.
    """
    url = _clean_text(item.get("url"))
    host = _normalize_host(url)
    if primary:
        return True
    if host == "sec.gov" or host.endswith(".sec.gov"):
        return True

    sample = " ".join([
        item.get("title") or "",
        item.get("snippet") or "",
        (page_text or "")[:12_000],
    ]).lower()
    compact_sample = re.sub(r"[^a-z0-9äöüß]+", "", sample)
    tokens = _company_identity_tokens(company_name)
    if any(token in sample or token in compact_sample for token in tokens):
        return True

    sym = _clean_text(symbol).upper()
    if len(sym) >= 3:
        if re.search(rf"\b(?:nyse|nasdaq|ticker)\s*[:\-]?\s*{re.escape(sym)}\b", sample, flags=re.I):
            return True
        if re.search(rf"\({re.escape(sym)}\)", sample, flags=re.I):
            return True
    return False


def _eps_number(raw):
    if raw is None:
        return None
    s = str(raw).strip().replace(",", ".")
    negative = s.startswith("(") and s.endswith(")")
    s = s.strip("()")
    try:
        value = float(s)
    except Exception:
        return None
    if negative:
        value = -value
    if abs(value) > 50:
        return None
    return value


def _marker_is_comparative(text, start):
    """Reject period mentions that only describe the comparison period."""
    t = _clean_text(text)
    before = t[max(0, start - 180):start].lower()
    comparative_phrases = [
        "compared with", "compared to", "versus", " vs ", "year-ago",
        "year ago", "prior-year", "prior year", "same quarter of",
        "same period of", "same period in", "from the second quarter of",
        "from the first quarter of", "from the third quarter of",
        "from the fourth quarter of",
    ]
    return any(phrase in before for phrase in comparative_phrases)


def _period_markers(text, include_comparatives=False):
    """
    Return explicit reporting-period markers.

    V2.20.17 adds annual-title forms such as "Reports 2025 Results" and
    suppresses comparison-period phrases by default.
    """
    t = _clean_text(text)
    patterns = [
        (r"\b(?:full[-\s]?year|fiscal\s+year|fy)\s*(20\d{2})\b", lambda m: f"FY {m.group(1)}"),
        (r"\b(20\d{2})\s+(?:full[-\s]?year|fiscal\s+year|annual)\b", lambda m: f"FY {m.group(1)}"),
        (r"\breports?\s+(20\d{2})\s+(?:full[-\s]?year\s+)?results\b", lambda m: f"FY {m.group(1)}"),
        (r"\b(?:annual|full[-\s]?year)\s+results(?:\s+for)?\s*(20\d{2})\b", lambda m: f"FY {m.group(1)}"),
        (r"\b(first|second|third|fourth)\s+quarter(?:\s+(?:of|ended))?\s*(20\d{2})\b",
         lambda m: f"Q{('first','second','third','fourth').index(m.group(1).lower()) + 1} {m.group(2)}"),
        (r"\bq([1-4])\s*[-/]?\s*(20\d{2})\b", lambda m: f"Q{m.group(1)} {m.group(2)}"),
        (r"\b(?:year\s+ended|year\s+ending)\s+[^.]{0,45}?(20\d{2})\b", lambda m: f"FY {m.group(1)}"),
    ]
    out = []
    for pat, formatter in patterns:
        for m in re.finditer(pat, t, flags=re.I):
            try:
                label = formatter(m)
            except Exception:
                continue
            comparative = _marker_is_comparative(t, m.start())
            if comparative and not include_comparatives:
                continue
            out.append((m.start(), m.end(), label, comparative))
    out.sort(key=lambda row: row[0])
    return out


def _document_period_from_title(title):
    """
    Extract an authoritative report period only when the title is unambiguous.

    A title such as "Second Quarter 2026 Results" is authoritative and must not
    be overwritten by a later phrase like "compared with second quarter 2025".
    Titles containing both quarter and full-year periods intentionally remain
    unresolved so the local EPS table/paragraph can decide.
    """
    title = _clean_text(title)
    if not title:
        return None
    markers = _period_markers(title, include_comparatives=False)
    unique = list(dict.fromkeys(row[2] for row in markers))
    return unique[0] if len(unique) == 1 else None


def _period_for_span(text, start, end, title=None):
    t = _clean_text(text)
    title_period = _document_period_from_title(title)

    context = t[max(0, start - 260):min(len(t), end + 240)].lower()
    guidance = any(x in context for x in [
        "guidance", "outlook", "expects", "expected to be", "forecast",
        "full-year adjusted eps guidance", "adjusted eps guidance",
    ])

    # V2.20.17: a single explicit report period in the document title is the
    # strongest current-period signal. Comparison-year wording in the body may
    # never override it.
    if title_period is not None:
        return title_period, guidance

    markers = _period_markers(t, include_comparatives=False)
    prior = [row for row in markers if row[0] <= start and start - row[0] <= 900]
    marker = prior[-1] if prior else None
    if marker is None:
        near = [row for row in markers if row[0] <= end + 180 and row[1] >= start - 180]
        marker = near[0] if near else None

    period = marker[2] if marker else None
    return period, guidance


def _bridge_period_rank(period, target_year=None, guidance=False):
    """Higher is better: latest completed FY > other FY > quarter > guidance/unknown."""
    p = _clean_text(period).upper()
    if guidance:
        return 0
    if target_year is not None and p == f"FY {int(target_year)}":
        return 5
    if p.startswith("FY "):
        return 4
    if p.startswith("Q"):
        return 3
    if p:
        return 1
    return 0


def _bridge_row_sort_key(row, target_year=None):
    bridge = row.get("eps_bridge_values") or {}
    return (
        _bridge_period_rank(
            bridge.get("period"),
            target_year=target_year,
            guidance=bool(bridge.get("guidance")),
        ),
        1 if row.get("primary_source") else 0,
        float(row.get("bridge_score") or 0),
    )


def _eps_candidates(text, kind):
    t = _clean_text(text)
    num = r"(\(?-?\d+(?:[\.,]\d+)?\)?)"
    if kind == "gaap":
        patterns = [
            rf"(?:u\.?s\.?\s*)?gaap\s+(?:net\s+)?(?:earnings|loss)(?:\s+per\s+diluted\s+share)?\s*(?:were|was|of|:|=)?\s*\$?\s*{num}\s*(?:per\s+diluted\s+share)?",
            rf"(?:u\.?s\.?\s*)?gaap\s+(?:diluted\s+)?(?:eps|earnings\s+per\s+share)\s*(?:were|was|of|:|=)?\s*\$?\s*{num}",
            rf"reported\s+(?:diluted\s+)?(?:eps|earnings\s+per\s+share)\s*(?:were|was|of|:|=)?\s*\$?\s*{num}",
        ]
    else:
        patterns = [
            rf"adjusted\s+(?:net\s+)?earnings(?:\s+per\s+diluted\s+share)?\s*(?:were|was|of|:|=)?\s*\$?\s*{num}\s*(?:per\s+diluted\s+share)?",
            rf"adjusted\s+(?:diluted\s+)?(?:eps|earnings\s+per\s+share)\s*(?:were|was|of|:|=)?\s*\$?\s*{num}",
            rf"adj\.?\s+(?:diluted\s+)?eps\s*(?:were|was|of|:|=)?\s*\$?\s*{num}",
        ]

    out = []
    for pat in patterns:
        for m in re.finditer(pat, t, flags=re.I):
            raw = m.group(1)
            value = _eps_number(raw)
            if value is None:
                continue
            # Never treat a percentage as EPS.
            tail = t[m.end(1):m.end(1) + 5]
            if re.match(r"\s*%", tail):
                continue
            out.append({"value": value, "start": m.start(), "end": m.end(), "raw": m.group(0)})
    # dedupe overlapping regex variants
    deduped = []
    for row in sorted(out, key=lambda x: (x["start"], x["end"] - x["start"])):
        if any(abs(row["start"] - old["start"]) < 8 and abs(row["value"] - old["value"]) < 1e-9 for old in deduped):
            continue
        deduped.append(row)
    return deduped


def _noncomparable_per_share_values(text, start, end):
    t = _clean_text(text)
    context_start = max(0, start - 220)
    context_end = min(len(t), end + 260)
    context = t[context_start:context_end]
    num = r"(\(?-?\d+(?:[\.,]\d+)?\)?)"
    patterns = [
        rf"excluding\s+\$?\s*{num}\s+of\s+net\s+(?:losses|gains)[^.{{}}]{{0,120}}?per\s+diluted\s+share[^.{{}}]{{0,140}}?non[-\s]?comparable",
        rf"non[-\s]?comparable\s+items[^.{{}}]{{0,130}}?\$?\s*{num}\s+per\s+diluted\s+share",
    ]
    values = []
    for pat in patterns:
        for m in re.finditer(pat, context, flags=re.I):
            value = _eps_number(m.group(1))
            if value is not None:
                values.append(abs(value))
    return values


def _extract_eps_bridge_values(text, title=None):
    """
    V2.20.17: Extract explicitly labelled, same-period GAAP and adjusted EPS values with period validation.
    Both values must belong to the same local reporting period. Percentages are
    rejected. A reconciliation amount for non-comparable items is validated
    when it is available. Values remain diagnostic only.
    """
    t = _clean_text(text)
    if not t:
        return None

    gaap_rows = _eps_candidates(t, "gaap")
    adj_rows = _eps_candidates(t, "adjusted")
    candidates = []
    current_year = datetime.now().year

    for g in gaap_rows:
        for a in adj_rows:
            left = min(g["start"], a["start"])
            right = max(g["end"], a["end"])
            distance = right - left
            if distance > 700:
                continue

            g_period, g_guidance = _period_for_span(t, g["start"], g["end"], title=title)
            a_period, a_guidance = _period_for_span(t, a["start"], a["end"], title=title)
            if g_period and a_period and g_period != a_period:
                continue
            period = g_period or a_period
            guidance = bool(g_guidance or a_guidance)

            # Same-period requirement: when no explicit period marker exists,
            # accept only a very tight sentence-like span.
            if period is None and distance > 320:
                continue

            diff = abs(a["value"] - g["value"])
            recon_values = _noncomparable_per_share_values(t, left, right)
            recon_amount = None
            reconciliation_ok = False
            if recon_values:
                recon_amount = min(recon_values, key=lambda x: abs(x - diff))
                reconciliation_ok = abs(recon_amount - diff) <= max(0.04, diff * 0.04)

            score = 80.0 - distance / 25.0
            if period and period.startswith("FY") and not guidance:
                score += 70
            elif period and period.startswith("Q") and not guidance:
                score += 40
            elif guidance:
                score -= 35
            if period == f"FY {current_year - 1}":
                score += 25
            if reconciliation_ok:
                score += 45
            if "$" in g["raw"] or "$" in a["raw"]:
                score += 5

            candidates.append({
                "gaap_eps": g["value"],
                "adjusted_eps": a["value"],
                "period": period or "Zeitraum lokal eindeutig",
                "guidance": guidance,
                "noncomparable_per_share": recon_amount,
                "reconciliation_ok": reconciliation_ok,
                "bridge_delta": diff,
                "validation": (
                    "Explizite GAAP-/Adjusted-EPS-Labels, gleicher Zeitraum"
                    + (" und rechnerische Non-Comparable-Reconciliation" if reconciliation_ok else "")
                ),
                "bridge_score": score,
                "source_excerpt": t[max(0, left - 160):min(len(t), right + 220)],
            })

    if not candidates:
        return None
    candidates.sort(key=lambda row: row.get("bridge_score", 0), reverse=True)
    return candidates[0]



