def _bank_snapshot_is_fresh(snapshot):
    if not isinstance(snapshot, dict):
        return False
    try:
        valid_until = datetime.strptime(
            snapshot.get("valid_until"), "%d.%m.%Y"
        ).date()
        return datetime.now().date() <= valid_until
    except Exception:
        return False


def calculate_bank_score_v1(snapshot, primary_source_complete):
    """
    Conservative 100-point bank score based only on bank-specific anchors.

    Components:
    - normalized ROTCE: 40 points
    - CET1 capital quality: 25 points
    - tangible book value growth: 20 points
    - earnings quality / verified special-item bridge: 15 points

    Generic revenue growth, FCF and net-debt/FCF are deliberately excluded.
    """
    result = {
        "available": False,
        "score": None,
        "quality": None,
        "rotce_points": None,
        "cet1_points": None,
        "tbv_growth_points": None,
        "earnings_quality_points": None,
        "rotce_normalized_pct": None,
        "cet1_reference_pct": None,
        "tbv_growth_yoy_pct": None,
        "significant_items_share_of_reported_eps": None,
        "note": None,
    }

    if not primary_source_complete or not isinstance(snapshot, dict):
        result["note"] = (
            "Bank-Score gesperrt: aktueller verifizierter Primärquellen-Snapshot "
            "mit ROTCE, TBVPS und CET1 fehlt oder ist abgelaufen."
        )
        return result

    rotce = safe_float(snapshot.get("rotce_ex_significant_items_pct"))
    cet1_std = safe_float(snapshot.get("cet1_standardized_pct"))
    cet1_adv = safe_float(snapshot.get("cet1_advanced_pct"))
    tbv_growth = safe_float(snapshot.get("tangible_book_value_growth_yoy_pct"))

    cet1_candidates = [x for x in [cet1_std, cet1_adv] if x is not None]
    cet1_ref = min(cet1_candidates) if cet1_candidates else None

    if rotce is None or cet1_ref is None or tbv_growth is None:
        result["note"] = (
            "Bank-Score gesperrt: mindestens eine bankspezifische Kernkomponente "
            "(normalisierter ROTCE, CET1 oder TBV-Wachstum) fehlt."
        )
        return result

    if rotce >= 22.0:
        rotce_points = 40
    elif rotce >= 18.0:
        rotce_points = 36
    elif rotce >= 15.0:
        rotce_points = 32
    elif rotce >= 12.0:
        rotce_points = 24
    elif rotce >= 10.0:
        rotce_points = 16
    elif rotce >= 8.0:
        rotce_points = 8
    else:
        rotce_points = 0

    if cet1_ref >= 13.5:
        cet1_points = 25
    elif cet1_ref >= 12.5:
        cet1_points = 20
    elif cet1_ref >= 11.5:
        cet1_points = 15
    elif cet1_ref >= 10.5:
        cet1_points = 8
    else:
        cet1_points = 0

    if tbv_growth >= 8.0:
        tbv_growth_points = 20
    elif tbv_growth >= 5.0:
        tbv_growth_points = 15
    elif tbv_growth >= 2.0:
        tbv_growth_points = 10
    elif tbv_growth >= 0.0:
        tbv_growth_points = 5
    else:
        tbv_growth_points = 0

    significant = safe_float(snapshot.get("significant_items_eps_effect"))
    reported_q_eps = safe_float(snapshot.get("quarter_eps_reported"))
    ex_q_eps = safe_float(snapshot.get("quarter_eps_ex_significant_items"))

    special_item_ratio = None
    if significant is None or abs(significant) <= 1e-12:
        earnings_quality_points = 15
    else:
        # A verified official bridge is mandatory when material special items exist.
        if (
            reported_q_eps is None
            or abs(reported_q_eps) <= 1e-12
            or ex_q_eps is None
            or rotce is None
        ):
            result["note"] = (
                "Bank-Score gesperrt: wesentliche Sonderposten sind vorhanden, "
                "aber die offizielle Bereinigungsbrücke ist nicht vollständig."
            )
            return result

        special_item_ratio = abs(significant / reported_q_eps)
        if special_item_ratio <= 0.25:
            earnings_quality_points = 12
        elif special_item_ratio <= 0.50:
            earnings_quality_points = 8
        else:
            earnings_quality_points = 4

    total = rotce_points + cet1_points + tbv_growth_points + earnings_quality_points
    if total >= 85:
        quality = "Sehr stark"
    elif total >= 70:
        quality = "Stark"
    elif total >= 55:
        quality = "Ausreichend"
    else:
        quality = "Schwach"

    result.update({
        "available": True,
        "score": total,
        "quality": quality,
        "rotce_points": rotce_points,
        "cet1_points": cet1_points,
        "tbv_growth_points": tbv_growth_points,
        "earnings_quality_points": earnings_quality_points,
        "rotce_normalized_pct": rotce,
        "cet1_reference_pct": cet1_ref,
        "tbv_growth_yoy_pct": tbv_growth,
        "significant_items_share_of_reported_eps": special_item_ratio,
        "note": (
            "Der Bank-Score verwendet ausschließlich bankspezifische Qualitäts- und "
            "Kapitalanker. Umsatzwachstum, Standard-FCF und Netto-Schulden/FCF "
            "fließen nicht ein."
        ),
    })
    return result


def calculate_bank_core_eps_v1(
    info,
    snapshot,
    eps_normalization,
    primary_source_complete,
):
    """Build a fully covered, source-verified Core-TTM EPS basis for banks.

    V2.20.39 requires four consecutive official quarterly observations.  Each
    quarter must carry reported EPS, Core/ex-significant-items EPS, the signed
    special-item effect and an official source URL.  The official reported EPS
    sum must reconcile to Yahoo TTM EPS within a small rounding tolerance.
    Forward EPS is never adjusted by assumption.
    """
    result = {
        "available": False,
        "trailing_eps_reported": None,
        "official_ttm_reported_eps": None,
        "ttm_special_items_eps_effect": None,
        "core_trailing_eps": None,
        "forward_eps": None,
        "trailing_weight": None,
        "forward_weight": None,
        "bank_normalized_core_eps": None,
        "coverage_periods": [],
        "coverage_complete": False,
        "coverage_reconciliation_diff": None,
        "coverage_count": 0,
        "integration_version": BANK_TTM_COVERAGE_INTEGRATION_VERSION,
        "confidence": None,
        "note": None,
    }

    if not primary_source_complete or not isinstance(snapshot, dict):
        result["note"] = (
            "Bank-Core-EPS gesperrt: aktueller verifizierter Primärquellen-Snapshot "
            "fehlt oder ist abgelaufen."
        )
        return result

    trailing = safe_float((info or {}).get("trailingEps"))
    forward = safe_float((info or {}).get("forwardEps"))
    if trailing is None or trailing <= 0 or forward is None or forward <= 0:
        result["note"] = (
            "Bank-Core-EPS gesperrt: positive TTM- und Forward-EPS müssen gleichzeitig vorliegen."
        )
        return result

    coverage = snapshot.get("ttm_eps_coverage")
    expected = snapshot.get("ttm_coverage_expected_periods")
    if not isinstance(coverage, list) or not isinstance(expected, list) or len(expected) != 4:
        result["note"] = (
            "Bank-Core-EPS gesperrt: die erwartete Vier-Quartals-TTM-Abdeckung ist nicht definiert."
        )
        return result

    rows_by_period = {}
    validated_rows = []
    for row in coverage:
        if not isinstance(row, dict):
            continue
        period = str(row.get("period") or "").strip()
        if not period or period in rows_by_period:
            result["note"] = "Bank-Core-EPS gesperrt: TTM-Quartale fehlen oder sind doppelt."
            return result
        reported = safe_float(row.get("reported_eps"))
        core = safe_float(row.get("core_eps"))
        effect = safe_float(row.get("special_items_eps_effect"))
        source_url = str(row.get("source_url") or "")
        status = str(row.get("special_item_status") or "").strip()
        if reported is None or core is None or effect is None or not source_url or not status:
            result["note"] = (
                f"Bank-Core-EPS gesperrt: Primärquellen-Abdeckung für {period or 'ein Quartal'} ist unvollständig."
            )
            return result
        if "jpmorganchase.com" not in source_url.lower():
            result["note"] = (
                f"Bank-Core-EPS gesperrt: Quelle für {period} ist keine verifizierte JPMorgan-Primärquelle."
            )
            return result
        bridge_diff = reported - core
        bridge_tol = max(0.02, abs(effect) * 0.05)
        if abs(bridge_diff - effect) > bridge_tol:
            result["note"] = (
                f"Bank-Core-EPS gesperrt: Reported-/Core-EPS-Brücke für {period} stimmt nicht "
                "mit dem ausgewiesenen Sondereffekt überein."
            )
            return result
        normalized_row = dict(row)
        normalized_row.update({
            "reported_eps": reported,
            "core_eps": core,
            "special_items_eps_effect": effect,
        })
        rows_by_period[period] = normalized_row

    if set(rows_by_period) != set(expected) or len(rows_by_period) != 4:
        missing = [p for p in expected if p not in rows_by_period]
        result["note"] = (
            "Bank-Core-EPS gesperrt: Vier-Quartals-TTM-Abdeckung unvollständig"
            + (f"; fehlend: {', '.join(missing)}." if missing else ".")
        )
        return result

    validated_rows = [rows_by_period[p] for p in expected]
    official_reported_ttm = sum(r["reported_eps"] for r in validated_rows)
    official_core_ttm = sum(r["core_eps"] for r in validated_rows)
    total_effect = sum(r["special_items_eps_effect"] for r in validated_rows)

    # Yahoo and official quarterly EPS can differ by a cent or two because the
    # four source quarters are published rounded to cents.  Larger differences
    # indicate a period/unit mismatch and fail closed.
    reconciliation_diff = trailing - official_reported_ttm
    reconciliation_tol = max(0.10, abs(trailing) * 0.01)
    if abs(reconciliation_diff) > reconciliation_tol:
        result.update({
            "official_ttm_reported_eps": official_reported_ttm,
            "coverage_periods": validated_rows,
            "coverage_reconciliation_diff": reconciliation_diff,
        })
        result["note"] = (
            "Bank-Core-EPS gesperrt: Summe der vier offiziellen Quartals-EPS stimmt nicht "
            "ausreichend mit dem aktuellen Yahoo-TTM-EPS überein."
        )
        return result

    trailing_weight = safe_float((eps_normalization or {}).get("eps_used_trailing_weight"))
    forward_weight = safe_float((eps_normalization or {}).get("eps_used_forward_weight"))
    if trailing_weight is None or forward_weight is None:
        result["note"] = (
            "Bank-Core-EPS gesperrt: die konservativen TTM-/Forward-Gewichte der "
            "EPS-Normalisierung sind nicht eindeutig verfügbar."
        )
        return result

    weight_sum = trailing_weight + forward_weight
    if abs(weight_sum - 1.0) > 1e-6 or trailing_weight < 0 or forward_weight < 0:
        result["note"] = "Bank-Core-EPS gesperrt: TTM-/Forward-Gewichte sind nicht konsistent."
        return result

    if official_core_ttm <= 0:
        result["note"] = "Bank-Core-EPS gesperrt: das vollständig bereinigte Core-TTM-EPS ist nicht positiv."
        return result

    bank_normalized = trailing_weight * official_core_ttm + forward_weight * forward
    if bank_normalized <= 0:
        result["note"] = "Bank-Core-EPS gesperrt: die bereinigte Gewinnbasis ist nicht positiv."
        return result

    result.update({
        "available": True,
        "trailing_eps_reported": trailing,
        "official_ttm_reported_eps": official_reported_ttm,
        "ttm_special_items_eps_effect": total_effect,
        "core_trailing_eps": official_core_ttm,
        "forward_eps": forward,
        "trailing_weight": trailing_weight,
        "forward_weight": forward_weight,
        "bank_normalized_core_eps": bank_normalized,
        "coverage_periods": validated_rows,
        "coverage_complete": True,
        "coverage_reconciliation_diff": reconciliation_diff,
        "coverage_count": len(validated_rows),
        "integration_version": BANK_TTM_COVERAGE_INTEGRATION_VERSION,
        "confidence": "Hoch",
        "note": (
            f"TTM-Coverage Gate bestanden: {', '.join(expected)} sind einzeln aus offiziellen "
            f"Bankquellen abgedeckt. Offizielle Reported-EPS-Summe {official_reported_ttm:.2f}, "
            f"vollständig bereinigtes Core-TTM-EPS {official_core_ttm:.2f}, saldierter "
            f"Sondereffekt {total_effect:+.2f}. Yahoo-TTM-Abweichung nur {reconciliation_diff:+.2f}. "
            f"Danach werden {trailing_weight * 100:.0f} % Core-TTM / "
            f"{forward_weight * 100:.0f} % Forward verwendet; Forward-EPS wird nicht um "
            "unbekannte zukünftige Sonderposten bereinigt."
        ),
    })
    return result

def calculate_bank_valuation_v1(
    bank_score,
    snapshot,
    bank_core_eps,
    pb_consistency_status,
    forward_pe_status,
    source_consistency_note,
):
    """Dual-anchor bank valuation: 60% P/TBV and 40% bank-normalized Core P/E."""
    result = {
        "available": False,
        "bank_score": None,
        "ptbv_corridor_lower": 0.8,
        "ptbv_corridor_upper": 3.2,
        "pe_corridor_lower": 8.0,
        "pe_corridor_upper": 15.0,
        "target_ptbv": None,
        "target_pe": None,
        "tbv_per_share": None,
        "normalized_eps": None,
        "fair_value_tbv_financial": None,
        "fair_value_earnings_financial": None,
        "fair_value_financial": None,
        "tbv_weight": 0.60,
        "earnings_weight": 0.40,
        "anchor_spread_pct": None,
        "confidence_cap": "Mittel bis Hoch",
        "note": None,
    }

    if not isinstance(bank_score, dict) or not bank_score.get("available"):
        result["note"] = "Bankbewertung gesperrt: kein vollständiger Bank-Score verfügbar."
        return result

    if not isinstance(snapshot, dict):
        result["note"] = "Bankbewertung gesperrt: Primärquellen-Snapshot fehlt."
        return result

    if pb_consistency_status == "conflict" or forward_pe_status == "conflict":
        result["note"] = (
            "Bankbewertung gesperrt: eine Kurs-/Buchwert- oder KGV-"
            "Plausibilitätsprüfung zeigt einen Einheiten-/Quellenkonflikt."
        )
        return result

    if str(source_consistency_note or "").startswith("⚠️"):
        result["note"] = (
            "Bankbewertung gesperrt: offizieller Buchwert und Yahoo-Buchwert "
            "weichen materiell voneinander ab."
        )
        return result

    normalized_eps = safe_float((bank_core_eps or {}).get("bank_normalized_core_eps"))
    tbv = safe_float(snapshot.get("tangible_book_value_per_share"))
    score = safe_float(bank_score.get("score"))

    coverage_rows = (bank_core_eps or {}).get("coverage_periods") or []
    coverage_integrated = bool(
        isinstance(bank_core_eps, dict)
        and bank_core_eps.get("integration_version") == BANK_TTM_COVERAGE_INTEGRATION_VERSION
        and bank_core_eps.get("coverage_complete")
        and safe_float(bank_core_eps.get("coverage_count")) == 4
        and len(coverage_rows) == 4
    )
    if not coverage_integrated:
        result["note"] = (
            "Bankbewertung gesperrt: der Core-KGV-Anker stammt nicht aus der aktuell "
            "integrierten Vier-Quartals-TTM-Abdeckung. Veraltete oder teilbereinigte "
            "Core-EPS-Pfade werden nicht akzeptiert."
        )
        return result

    if (
        normalized_eps is None
        or normalized_eps <= 0
        or not isinstance(bank_core_eps, dict)
        or not bank_core_eps.get("available")
        or tbv is None
        or tbv <= 0
        or score is None
    ):
        result["note"] = (
            "Bankbewertung gesperrt: bank-normalisierte Core-EPS-Basis und "
            "verifiziertes Tangible Book Value je Aktie müssen gleichzeitig vorliegen."
        )
        return result

    score_fraction = max(0.0, min(1.0, score / 100.0))
    target_ptbv = 0.8 + (3.2 - 0.8) * score_fraction
    target_pe = 8.0 + (15.0 - 8.0) * score_fraction

    fair_tbv = tbv * target_ptbv
    fair_earnings = normalized_eps * target_pe

    if fair_tbv <= 0 or fair_earnings <= 0:
        result["note"] = "Bankbewertung gesperrt: mindestens ein Bewertungsanker ist nicht positiv."
        return result

    anchor_spread = abs(fair_tbv / fair_earnings - 1.0)
    if anchor_spread > 0.25:
        result.update({
            "bank_score": score,
            "target_ptbv": target_ptbv,
            "target_pe": target_pe,
            "tbv_per_share": tbv,
            "normalized_eps": normalized_eps,
            "fair_value_tbv_financial": fair_tbv,
            "fair_value_earnings_financial": fair_earnings,
            "anchor_spread_pct": anchor_spread * 100.0,
            "note": (
                "Bankbewertung gesperrt: P/TBV- und KGV-Anker weichen um mehr als "
                "25 % voneinander ab. Die beiden Bewertungswege sind nicht ausreichend konsistent."
            ),
        })
        return result

    fair_blended = 0.60 * fair_tbv + 0.40 * fair_earnings
    result.update({
        "available": True,
        "bank_score": score,
        "target_ptbv": target_ptbv,
        "target_pe": target_pe,
        "tbv_per_share": tbv,
        "normalized_eps": normalized_eps,
        "fair_value_tbv_financial": fair_tbv,
        "fair_value_earnings_financial": fair_earnings,
        "fair_value_financial": fair_blended,
        "anchor_spread_pct": anchor_spread * 100.0,
        "note": (
            "Bank-Fair-Value V1 kombiniert 60 % Tangible-Book-Value-Anker "
            "(P/TBV) und 40 % bank-normalisierte Core-Gewinnbasis (KGV). Der Bank-Score "
            "bestimmt beide Zielkorridore linear. Bei mehr als 25 % Abstand "
            "zwischen den beiden Fair-Value-Ankern bleibt die Bewertung gesperrt."
        ),
    })
    return result


def build_bank_special_model(
    company_type,
    info,
    price,
    currency_context,
    symbol=None,
    eps_normalization=None,
):
    """
    Bank-specific primary-source, score and dual-anchor valuation block.

    V2.20.39 keeps the verified ROTCE/TBV/CET1 gate and adds a dedicated
    bank score plus a conservative P/TBV + bank-normalized Core-P/E valuation.
    """
    type_name = str(company_type.get("type", "")).lower()

    if "bank" not in type_name:
        return {
            "applicable": False
        }

    quote_price = safe_float(price)
    price_financial = convert_quote_price_to_financial_share_unit(
        quote_price,
        currency_context
    )

    book_value = safe_float(info.get("bookValue"))
    roe = safe_float(info.get("returnOnEquity"))
    trailing_eps = safe_float(info.get("trailingEps"))
    forward_eps = safe_float(info.get("forwardEps"))
    yahoo_price_to_book = safe_float(info.get("priceToBook"))
    yahoo_forward_pe = safe_float(info.get("forwardPE"))
    if yahoo_forward_pe is None:
        yahoo_forward_pe = safe_float(info.get("forwardPe"))

    calculated_price_to_book = None
    if (
        price_financial is not None
        and price_financial > 0
        and book_value is not None
        and book_value > 0
    ):
        calculated_price_to_book = price_financial / book_value

    pb_display_value = None
    pb_consistency_status = "unverified"
    pb_consistency_note = None

    if calculated_price_to_book is None:
        pb_consistency_note = (
            "KBV konnte aus Kurs und Buchwert je Aktie nicht belastbar "
            "berechnet werden. Es wird kein Wert geschätzt."
        )
    elif yahoo_price_to_book is not None and yahoo_price_to_book > 0:
        pb_deviation = abs(calculated_price_to_book / yahoo_price_to_book - 1.0)
        if pb_deviation <= 0.20:
            pb_display_value = calculated_price_to_book
            pb_consistency_status = "plausible"
            pb_consistency_note = (
                "KBV-Plausibilitätscheck bestanden: Das aus Kurs und "
                "Buchwert je Aktie berechnete KBV liegt innerhalb von "
                "20 % des separat gemeldeten Yahoo-KBV."
            )
        else:
            pb_consistency_status = "conflict"
            pb_consistency_note = (
                "⚠️ KBV-Einheiten/Plausibilität widersprüchlich: Das aus "
                "Kurs und Buchwert je Aktie berechnete KBV weicht um mehr "
                "als 20 % vom separat gemeldeten Yahoo-KBV ab."
            )
    else:
        pb_consistency_note = (
            "KBV konnte zwar aus Kurs und Buchwert je Aktie berechnet werden, "
            "aber ein zweiter Yahoo-KBV-Anker fehlt."
        )

    calculated_forward_pe = None
    if (
        price_financial is not None
        and price_financial > 0
        and forward_eps is not None
        and forward_eps > 0
    ):
        calculated_forward_pe = price_financial / forward_eps

    forward_pe_display = None
    forward_pe_status = "unverified"
    forward_pe_note = None

    if calculated_forward_pe is None:
        forward_pe_note = (
            "Forward-KGV konnte aus Kurs und Forward-EPS nicht belastbar "
            "berechnet werden. Es wird kein Wert geschätzt."
        )
    elif yahoo_forward_pe is not None and yahoo_forward_pe > 0:
        pe_deviation = abs(calculated_forward_pe / yahoo_forward_pe - 1.0)
        if pe_deviation <= 0.20:
            forward_pe_display = calculated_forward_pe
            forward_pe_status = "plausible"
            forward_pe_note = (
                "Forward-KGV-Plausibilitätscheck bestanden: Kurs/Forward-EPS "
                "und Yahoo-forwardPE liegen innerhalb von 20 % beieinander."
            )
        else:
            forward_pe_status = "conflict"
            forward_pe_note = (
                "⚠️ Forward-KGV nicht belastbar: Das aus Kurs und Forward-EPS "
                "berechnete KGV weicht um mehr als 20 % vom Yahoo-forwardPE ab."
            )
    else:
        forward_pe_note = (
            "Forward-KGV konnte berechnet werden, aber ein separater Yahoo-"
            "forwardPE-Anker fehlt."
        )

    calculated_trailing_pe = None
    if (
        price_financial is not None
        and price_financial > 0
        and trailing_eps is not None
        and trailing_eps > 0
    ):
        calculated_trailing_pe = price_financial / trailing_eps

    snapshot = get_verified_bank_snapshot(symbol)
    snapshot_fresh = _bank_snapshot_is_fresh(snapshot)

    primary_book_value = None
    tangible_book_value = None
    rote_reported = None
    rote_normalized = None
    cet1_standardized = None
    cet1_advanced = None
    price_to_tangible_book = None
    source_consistency_note = None
    primary_source_complete = False

    if snapshot is not None:
        primary_book_value = safe_float(snapshot.get("book_value_per_share"))
        tangible_book_value = safe_float(snapshot.get("tangible_book_value_per_share"))
        rote_reported = safe_float(snapshot.get("rotce_reported_pct"))
        rote_normalized = safe_float(snapshot.get("rotce_ex_significant_items_pct"))
        cet1_standardized = safe_float(snapshot.get("cet1_standardized_pct"))
        cet1_advanced = safe_float(snapshot.get("cet1_advanced_pct"))

        if (
            price_financial is not None
            and price_financial > 0
            and tangible_book_value is not None
            and tangible_book_value > 0
        ):
            price_to_tangible_book = price_financial / tangible_book_value

        if book_value is not None and primary_book_value is not None and primary_book_value > 0:
            source_deviation = abs(book_value / primary_book_value - 1.0)
            if source_deviation <= 0.05:
                source_consistency_note = (
                    "Primärquellen-Abgleich bestanden: Yahoo-Buchwert je Aktie "
                    "und offizieller JPMorgan-Buchwert liegen innerhalb von 5 %."
                )
            else:
                source_consistency_note = (
                    "⚠️ Primärquellen-Abweichung: Yahoo-Buchwert je Aktie und "
                    "offizieller Buchwert weichen um mehr als 5 % voneinander ab."
                )

        primary_source_complete = all(
            value is not None
            for value in [
                tangible_book_value,
                rote_normalized,
                cet1_standardized,
            ]
        ) and snapshot_fresh

    if primary_source_complete:
        readiness = "Primärdaten vollständig"
    elif snapshot is not None and not snapshot_fresh:
        readiness = "Primärdaten veraltet"
    else:
        anchor_values = [roe, pb_display_value, forward_pe_display]
        available_anchors = sum(value is not None for value in anchor_values)
        readiness = "Teilweise" if available_anchors >= 2 else "Unvollständig"

    bank_score = calculate_bank_score_v1(snapshot, primary_source_complete)
    bank_core_eps = calculate_bank_core_eps_v1(
        info,
        snapshot,
        eps_normalization,
        primary_source_complete,
    )
    bank_valuation = calculate_bank_valuation_v1(
        bank_score,
        snapshot,
        bank_core_eps,
        pb_consistency_status,
        forward_pe_status,
        source_consistency_note,
    )

    return {
        "applicable": True,
        "price_financial": price_financial,
        "book_value_per_share": book_value,
        "roe": roe,
        "calculated_price_to_book": calculated_price_to_book,
        "display_price_to_book": pb_display_value,
        "yahoo_price_to_book": yahoo_price_to_book,
        "pb_consistency_status": pb_consistency_status,
        "pb_consistency_note": pb_consistency_note,
        "calculated_forward_pe": calculated_forward_pe,
        "display_forward_pe": forward_pe_display,
        "yahoo_forward_pe": yahoo_forward_pe,
        "forward_pe_status": forward_pe_status,
        "forward_pe_note": forward_pe_note,
        "calculated_trailing_pe": calculated_trailing_pe,
        "snapshot": snapshot,
        "snapshot_fresh": snapshot_fresh,
        "primary_source_complete": primary_source_complete,
        "primary_book_value_per_share": primary_book_value,
        "tangible_book_value_per_share": tangible_book_value,
        "price_to_tangible_book": price_to_tangible_book,
        "rote_reported_pct": rote_reported,
        "rote_normalized_pct": rote_normalized,
        "cet1_standardized_pct": cet1_standardized,
        "cet1_advanced_pct": cet1_advanced,
        "source_consistency_note": source_consistency_note,
        "readiness": readiness,
        "rote_available": rote_normalized is not None and snapshot_fresh,
        "tangible_book_value_available": tangible_book_value is not None and snapshot_fresh,
        "cet1_available": cet1_standardized is not None and snapshot_fresh,
        "bank_score": bank_score,
        "bank_core_eps": bank_core_eps,
        "bank_valuation": bank_valuation,
        "note": (
            "Banken-Sondermodell V2.20.39 lädt verifizierte Primärquellen-"
            "Kennzahlen und verwendet ausschließlich bankspezifische Faktoren "
            "für den Bank-Score. Bei vollständiger Datenbasis wird ein "
            "Dual-Anchor-Fair-Value aus 60 % P/TBV und 40 % bank-normalisiertem Core-KGV "
            "berechnet. Der Core-KGV-Anker wird nur bei vollständiger Vier-Quartals-TTM-"
            "Abdeckung freigegeben. Standard-FCF und Netto-Schulden/FCF bleiben ausgeschlossen."
        )
    }


def build_bank_special_control(base_control, bank_model):
    """Attach a fail-closed Bank step 3B primary-source gate."""
    control = dict(base_control or {})
    control.setdefault("router_status", control.get("status"))
    control.setdefault("router_note", control.get("note"))

    if control.get("control_key") != "bank_book_capital":
        return control

    model = bank_model if isinstance(bank_model, dict) else {}
    snapshot = model.get("snapshot")

    if not model.get("primary_source_complete"):
        control.update({
            "implemented": False,
            "released": False,
            "confidence_cap": "Niedrig",
            "step3b_status": "Primärdaten unvollständig oder veraltet",
            "overall_status": "Nicht freigegeben",
            "snapshot": snapshot,
            "note": (
                "Die Bank-Primärdatenprüfung benötigt aktuellen ROTCE, TBVPS "
                "und CET1 aus einer offiziellen Quelle. Fehlende Werte werden "
                "nicht durch ROE, normalen Buchwert oder Yahoo-Proxies ersetzt."
            ),
        })
        return control

    bank_score = model.get("bank_score") or {}
    bank_core_eps = model.get("bank_core_eps") or {}
    bank_valuation = model.get("bank_valuation") or {}

    valuation_released = bool(
        bank_score.get("available")
        and bank_core_eps.get("available")
        and bank_core_eps.get("integration_version") == BANK_TTM_COVERAGE_INTEGRATION_VERSION
        and bank_core_eps.get("coverage_complete")
        and safe_float(bank_core_eps.get("coverage_count")) == 4
        and len(bank_core_eps.get("coverage_periods") or []) == 4
        and bank_valuation.get("available")
    )

    control.update({
        "implemented": True,
        "released": valuation_released,
        "confidence_cap": (bank_valuation.get("confidence_cap") or "Mittel"),
        "step3b_status": (
            "Bankbewertung freigegeben – Dual-Anchor V1"
            if valuation_released
            else "Primärdaten vollständig – Bankbewertung noch gesperrt"
        ),
        "overall_status": (
            "Freigegeben" if valuation_released else "Primärdaten vollständig"
        ),
        "snapshot": snapshot,
        "checks": {
            "rote_reported_pct": model.get("rote_reported_pct"),
            "rote_normalized_pct": model.get("rote_normalized_pct"),
            "tangible_book_value_per_share": model.get("tangible_book_value_per_share"),
            "price_to_tangible_book": model.get("price_to_tangible_book"),
            "cet1_standardized_pct": model.get("cet1_standardized_pct"),
            "cet1_advanced_pct": model.get("cet1_advanced_pct"),
            "bank_score": bank_score,
            "bank_core_eps": bank_core_eps,
            "bank_valuation": bank_valuation,
        },
        "note": (
            "Bank-Schritt 3B V2.20.39 hat Primärdaten, Bank-Score, Vier-Quartals-TTM-Core-EPS-Abdeckung und beide "
            "Bewertungsanker validiert. Der Fair Value wird nur freigegeben, "
            "wenn P/TBV- und Core-KGV-Anker gleichzeitig belastbar und ausreichend "
            "konsistent sind."
            if valuation_released
            else (
                "Bank-Schritt 3B V2.20.39 hat die Primärdatenbasis validiert, "
                "aber die Bewertungsfreigabe bleibt gesperrt: "
                + str(bank_valuation.get("note") or bank_score.get("note") or "Bankbewertung unvollständig.")
            )
        ),
    })
    return control


# =========================================================
# Midstream-Sondermodell V2.20.49 – Primary Source FCF / Leverage Gate
# =========================================================

MIDSTREAM_PRIMARY_SOURCE_INTEGRATION_VERSION = "v22049_midstream_primary_fcf_leverage"


def get_verified_midstream_snapshot(symbol):
    """Time-bounded official Midstream snapshot for supported companies.

    V2.20.49 starts with Kinder Morgan (NYSE: KMI). Kinder Morgan currently
    reports issuer-defined FCF rather than a metric labelled DCF. We preserve
    that nomenclature and never relabel Yahoo FCF/OCF as issuer-defined DCF.
    """
    symbol_text = str(symbol or "").upper().strip()
    if symbol_text != "KMI":
        return None

    return {
        "company": "Kinder Morgan, Inc.",
        "as_of_date": "30.06.2026",
        "published_date": "22.07.2026",
        # Conservative expiry ahead of the normal Q3 reporting window.
        "valid_until": "20.10.2026",
        "source_name": "Kinder Morgan Q2 2026 Financial Results",
        "source_url": "https://ir.kindermorgan.com/news/news-details/2026/Kinder-Morgan-Reports-Second-Quarter-2026-Financial-Results/default.aspx",
        "period_label": "Q2 / 6M 2026",
        "cashflow_metric_name": "KMI FCF",

        # Official Table 6, USD millions.
        "fcf_q2_total": 978e6,
        "fcf_q2_prior_total": 1002e6,
        "fcf_h1_total": 1665e6,
        "fcf_h1_prior_total": 1398e6,
        "dividends_paid_q2_total": 665e6,
        "dividends_paid_h1_total": 1319e6,
        "fcf_after_dividends_q2_total": 313e6,
        "fcf_after_dividends_h1_total": 346e6,

        # Official per-share / earnings data.
        "weighted_avg_shares_m": 2225.0,
        "declared_dividend_q2_per_share": 0.2975,
        "annualized_dividend_per_share": 1.19,
        "adjusted_eps_q2": 0.37,
        "adjusted_eps_h1": 0.84,

        # Official adjusted EBITDA / balance-sheet anchors.
        "adjusted_ebitda_q2_total": 2199e6,
        "adjusted_ebitda_h1_total": 4738e6,
        "adjusted_ebitda_ltm_total": 9000e6,
        "net_debt_total": 32027e6,
        "net_debt_to_adjusted_ebitda": 3.6,

        # 2026 outlook / project visibility.
        "adjusted_ebitda_budget_2026": 8.6e9,
        "adjusted_ebitda_expected_vs_budget_min_pct": 5.0,
        "adjusted_eps_budget_2026": 1.36,
        "adjusted_eps_expected_vs_budget_min_pct": 12.0,
        "year_end_leverage_expected": 3.6,
        "project_backlog_total": 9.6e9,
        "project_backlog_natural_gas_share_pct": 92.0,
        "project_backlog_power_ldc_share_min_pct": 60.0,
        "project_backlog_multiple_scope_total": 8.5e9,
        "project_backlog_first_year_ebitda_multiple": 5.6,

        "source_note": (
            "Offizielle Kinder-Morgan-Q2/6M-2026-Daten. KMI FCF, Dividenden, "
            "Adjusted EBITDA, Net Debt / Adjusted EBITDA und Projekt-Backlog werden "
            "nicht aus Yahoo-Free-Cashflow, Operating Cashflow oder generischen "
            "EV/EBITDA-Proxies rekonstruiert. Kinder Morgan bezeichnet die aktuelle "
            "Cashflow-Kennzahl als FCF; die App erfindet daraus keinen DCF-Wert."
        ),
    }


def _midstream_snapshot_is_fresh(snapshot):
    if not isinstance(snapshot, dict):
        return False
    try:
        valid_until = datetime.strptime(snapshot.get("valid_until"), "%d.%m.%Y").date()
        return datetime.now().date() <= valid_until
    except Exception:
        return False


def build_midstream_primary_source_gate(snapshot):
    """Validate issuer-defined cashflow, dividend coverage, leverage and backlog."""
    result = {
        "available": False,
        "integration_version": MIDSTREAM_PRIMARY_SOURCE_INTEGRATION_VERSION,
        "cashflow_metric_name": None,
        "fcf_q2_total": None,
        "fcf_h1_total": None,
        "fcf_h1_growth_pct": None,
        "dividends_paid_q2_total": None,
        "dividends_paid_h1_total": None,
        "fcf_after_dividends_q2_total": None,
        "fcf_after_dividends_h1_total": None,
        "coverage_q2": None,
        "coverage_h1": None,
        "adjusted_ebitda_q2_total": None,
        "adjusted_ebitda_h1_total": None,
        "adjusted_ebitda_ltm_total": None,
        "net_debt_total": None,
        "net_debt_to_adjusted_ebitda": None,
        "project_backlog_total": None,
        "project_backlog_natural_gas_share_pct": None,
        "project_backlog_first_year_ebitda_multiple": None,
        "annualized_dividend_per_share": None,
        "note": None,
    }
    if not isinstance(snapshot, dict):
        result["note"] = (
            "Midstream-Primärquellen-Gate nicht verfügbar: kein verifizierter "
            "aktueller Midstream-Snapshot."
        )
        return result
    if not _midstream_snapshot_is_fresh(snapshot):
        result["note"] = (
            "Midstream-Primärquellen-Gate gesperrt: der offizielle Snapshot ist "
            "abgelaufen und muss vor einer Bewertung aktualisiert werden."
        )
        return result

    fcf_q2 = safe_float(snapshot.get("fcf_q2_total"))
    fcf_h1 = safe_float(snapshot.get("fcf_h1_total"))
    fcf_h1_prior = safe_float(snapshot.get("fcf_h1_prior_total"))
    div_q2 = safe_float(snapshot.get("dividends_paid_q2_total"))
    div_h1 = safe_float(snapshot.get("dividends_paid_h1_total"))
    after_q2 = safe_float(snapshot.get("fcf_after_dividends_q2_total"))
    after_h1 = safe_float(snapshot.get("fcf_after_dividends_h1_total"))
    ebitda_q2 = safe_float(snapshot.get("adjusted_ebitda_q2_total"))
    ebitda_h1 = safe_float(snapshot.get("adjusted_ebitda_h1_total"))
    ebitda_ltm = safe_float(snapshot.get("adjusted_ebitda_ltm_total"))
    net_debt = safe_float(snapshot.get("net_debt_total"))
    leverage = safe_float(snapshot.get("net_debt_to_adjusted_ebitda"))
    backlog = safe_float(snapshot.get("project_backlog_total"))
    gas_share = safe_float(snapshot.get("project_backlog_natural_gas_share_pct"))
    backlog_multiple = safe_float(snapshot.get("project_backlog_first_year_ebitda_multiple"))

    required = [fcf_q2, fcf_h1, div_q2, div_h1, ebitda_ltm, net_debt, leverage, backlog]
    if any(v is None or v <= 0 for v in required):
        result["note"] = (
            "Midstream-Primärquellen-Gate gesperrt: mindestens eine Pflichtkomponente "
            "aus issuer-definiertem FCF, Dividenden, Adjusted EBITDA, Net Debt oder "
            "Projekt-Backlog fehlt."
        )
        return result

    coverage_q2 = fcf_q2 / div_q2 if div_q2 > 0 else None
    coverage_h1 = fcf_h1 / div_h1 if div_h1 > 0 else None
    growth_h1 = ((fcf_h1 / fcf_h1_prior) - 1.0) * 100.0 if fcf_h1_prior and fcf_h1_prior > 0 else None

    result.update({
        "available": True,
        "cashflow_metric_name": snapshot.get("cashflow_metric_name") or "Issuer FCF/DCF",
        "fcf_q2_total": fcf_q2,
        "fcf_h1_total": fcf_h1,
        "fcf_h1_growth_pct": growth_h1,
        "dividends_paid_q2_total": div_q2,
        "dividends_paid_h1_total": div_h1,
        "fcf_after_dividends_q2_total": after_q2,
        "fcf_after_dividends_h1_total": after_h1,
        "coverage_q2": coverage_q2,
        "coverage_h1": coverage_h1,
        "adjusted_ebitda_q2_total": ebitda_q2,
        "adjusted_ebitda_h1_total": ebitda_h1,
        "adjusted_ebitda_ltm_total": ebitda_ltm,
        "net_debt_total": net_debt,
        "net_debt_to_adjusted_ebitda": leverage,
        "project_backlog_total": backlog,
        "project_backlog_natural_gas_share_pct": gas_share,
        "project_backlog_first_year_ebitda_multiple": backlog_multiple,
        "annualized_dividend_per_share": safe_float(snapshot.get("annualized_dividend_per_share")),
        "note": (
            "Midstream-Primärquellen-Gate bestanden: issuer-definierter Cashflow, "
            "Dividendendeckung, Adjusted EBITDA, Net Debt / Adjusted EBITDA und "
            "Projekt-Backlog stammen aus den offiziellen Kinder-Morgan-Q2/6M-2026-Unterlagen."
        ),
    })
    return result


def build_midstream_special_model(
    company_type,
    info,
    price,
    currency_context,
    symbol=None
):
    """Midstream-specific official-data gate plus Yahoo context.

    V2.20.49 still does not create a Midstream score, valuation multiple or
    fair value. It validates the minimum primary-source dataset needed for the
    next phase and keeps Yahoo EV/EBITDA/FCF strictly contextual.
    """
    type_name = str(company_type.get("type", "")).lower()
    if "midstream" not in type_name:
        return {"applicable": False}

    snapshot = get_verified_midstream_snapshot(symbol)
    snapshot_fresh = _midstream_snapshot_is_fresh(snapshot)
    primary_gate = build_midstream_primary_source_gate(snapshot)
    primary_source_complete = bool(snapshot_fresh and primary_gate.get("available"))

    enterprise_value = safe_float(info.get("enterpriseValue"))
    ebitda = safe_float(info.get("ebitda"))
    yahoo_ev_to_ebitda = safe_float(info.get("enterpriseToEbitda"))
    total_cash = safe_float(info.get("totalCash"))
    total_debt = safe_float(info.get("totalDebt"))
    operating_cashflow = safe_float(info.get("operatingCashflow"))
    free_cashflow_reference = safe_float(info.get("freeCashflow"))

    calculated_ev_to_ebitda = None
    if enterprise_value is not None and enterprise_value > 0 and ebitda is not None and ebitda > 0:
        calculated_ev_to_ebitda = enterprise_value / ebitda

    ev_to_ebitda_display = None
    ev_to_ebitda_status = "unverified"
    ev_to_ebitda_note = None
    if calculated_ev_to_ebitda is None:
        ev_to_ebitda_note = (
            "Yahoo-EV/EBITDA konnte aus Enterprise Value und EBITDA nicht belastbar "
            "berechnet werden. Es wird kein Wert geschätzt."
        )
    elif yahoo_ev_to_ebitda is not None and yahoo_ev_to_ebitda > 0:
        ev_deviation = abs(calculated_ev_to_ebitda / yahoo_ev_to_ebitda - 1.0)
        if ev_deviation <= 0.20:
            ev_to_ebitda_display = calculated_ev_to_ebitda
            ev_to_ebitda_status = "plausible"
            ev_to_ebitda_note = (
                "Yahoo-EV/EBITDA-Plausibilitätscheck bestanden. Der Wert bleibt nur "
                "Kontext; für die Midstream-Kernprüfung gilt das offizielle Adjusted EBITDA."
            )
        else:
            ev_to_ebitda_status = "conflict"
            ev_to_ebitda_note = (
                "⚠️ Yahoo-EV/EBITDA nicht belastbar: selbst berechnete Kennzahl und "
                "Yahoo-enterpriseToEbitda weichen um mehr als 20 % voneinander ab."
            )
    else:
        ev_to_ebitda_note = (
            "Yahoo-EV/EBITDA konnte berechnet werden, aber ein separater Yahoo-Anker fehlt. "
            "Der Wert wird nicht als belastbare Kernkennzahl verwendet."
        )

    net_debt = total_debt - total_cash if total_debt is not None and total_cash is not None else None
    net_debt_to_ebitda = (
        net_debt / ebitda
        if net_debt is not None and net_debt > 0 and ebitda is not None and ebitda > 0
        else None
    )

    available_anchors = sum(v is not None for v in [ev_to_ebitda_display, net_debt_to_ebitda, operating_cashflow])
    readiness = "Primärdaten vollständig" if primary_source_complete else ("Teilweise" if available_anchors >= 2 else "Unvollständig")

    return {
        "applicable": True,
        "snapshot": snapshot,
        "snapshot_fresh": snapshot_fresh,
        "primary_source_complete": primary_source_complete,
        "primary_gate": primary_gate,
        "integration_version": MIDSTREAM_PRIMARY_SOURCE_INTEGRATION_VERSION,
        "enterprise_value": enterprise_value,
        "ebitda": ebitda,
        "calculated_ev_to_ebitda": calculated_ev_to_ebitda,
        "display_ev_to_ebitda": ev_to_ebitda_display,
        "yahoo_ev_to_ebitda": yahoo_ev_to_ebitda,
        "ev_to_ebitda_status": ev_to_ebitda_status,
        "ev_to_ebitda_note": ev_to_ebitda_note,
        "total_cash": total_cash,
        "total_debt": total_debt,
        "net_debt": net_debt,
        "net_debt_to_ebitda": net_debt_to_ebitda,
        "operating_cashflow": operating_cashflow,
        "free_cashflow_reference": free_cashflow_reference,
        "distributable_cashflow_available": False,
        "readiness": readiness,
        "note": (
            "Midstream-Sondermodell V2.20.49 trennt offizielle issuer-definierte "
            "Cashflow-/Dividendendeckungs-, Adjusted-EBITDA-, Verschuldungs- und "
            "Backlog-Kennzahlen von Yahoo-Kontextdaten. Für KMI wird die offiziell "
            "gemeldete Kennzahl KMI FCF verwendet; ein DCF-Wert wird nicht erfunden. "
            "Noch kein Midstream-Score, kein Bewertungs-Multiple und kein Fair Value."
        ),
    }


def build_midstream_special_control(base_control, midstream_model):
    """Attach the fail-closed Midstream primary-source gate to step 3B."""
    control = dict(base_control or {})
    control.setdefault("router_status", control.get("status"))
    control.setdefault("router_note", control.get("note"))
    if control.get("control_key") != "midstream_cashflow_leverage":
        return control

    model = midstream_model if isinstance(midstream_model, dict) else {}
    snapshot = model.get("snapshot")
    gate = model.get("primary_gate") or {}

    if not model.get("primary_source_complete"):
        control.update({
            "implemented": False,
            "released": False,
            "confidence_cap": "Niedrig",
            "step3b_status": "Midstream-Primärdaten unvollständig oder veraltet",
            "overall_status": "Nicht freigegeben",
            "snapshot": snapshot,
            "checks": {"primary_gate": gate},
            "note": (
                "Die Midstream-Spezialkontrolle benötigt aktuelle offizielle "
                "issuer-definierte FCF/DCF-, Dividendendeckungs-, Adjusted-EBITDA-, "
                "Net-Debt- und Backlog-Daten. Fehlende Werte werden nicht aus Yahoo-FCF, "
                "Operating Cashflow oder generischen Bilanz-Proxies geschätzt."
            ),
        })
        return control

    control.update({
        "implemented": True,
        "released": False,
        "confidence_cap": "Mittel",
        "step3b_status": "Midstream-Primärquellen-Gate bestanden – Bewertungsmodell noch gesperrt",
        "overall_status": "Primärdaten freigegeben, Bewertung noch nicht freigegeben",
        "snapshot": snapshot,
        "checks": {
            "primary_gate": gate,
            **{k: gate.get(k) for k in [
                "cashflow_metric_name", "fcf_q2_total", "fcf_h1_total", "fcf_h1_growth_pct",
                "dividends_paid_q2_total", "dividends_paid_h1_total",
                "fcf_after_dividends_q2_total", "fcf_after_dividends_h1_total",
                "coverage_q2", "coverage_h1", "adjusted_ebitda_q2_total",
                "adjusted_ebitda_h1_total", "adjusted_ebitda_ltm_total", "net_debt_total",
                "net_debt_to_adjusted_ebitda", "project_backlog_total",
                "project_backlog_natural_gas_share_pct", "project_backlog_first_year_ebitda_multiple",
                "annualized_dividend_per_share"
            ]},
        },
        "note": (
            "Midstream-Schritt 3B V2.20.49 validiert die offizielle Cashflow-/"
            "Dividendendeckungsbasis, Adjusted EBITDA, Net Debt / Adjusted EBITDA und "
            "Projekt-Backlog. Primärdatenfreigabe und Bewertungsfreigabe bleiben getrennt: "
            "Score, EV/Adjusted-EBITDA-Zielkorridor und Fair Value folgen erst separat."
        ),
    })
    return control


# =========================================================
# Autohersteller-Sondermodell V1 – Datenbasis / Plausibilitätscheck
# =========================================================

def build_auto_special_model(
    company_type,
    info,
    eps_normalization,
    currency_context
):
    """
    Conservative auto-manufacturer data block.

    It does not create a score, valuation multiple or fair value.
    Consolidated Yahoo cash flow and debt can mix the industrial
    automotive business with captive financial services, so V1
    never treats them as automotive industrial FCF/net debt.
    """
    type_name = str(
        company_type.get("type", "")
    ).lower()

    if "autohersteller" not in type_name:
        return {
            "applicable": False
        }

    enterprise_value = safe_float(
        info.get("enterpriseValue")
    )
    ebitda = safe_float(
        info.get("ebitda")
    )
    yahoo_ev_to_ebitda = safe_float(
        info.get("enterpriseToEbitda")
    )
    operating_cashflow = safe_float(
        info.get("operatingCashflow")
    )
    free_cashflow_reference = safe_float(
        info.get("freeCashflow")
    )
    total_cash_reference = safe_float(
        info.get("totalCash")
    )
    total_debt_reference = safe_float(
        info.get("totalDebt")
    )

    normalized_eps = None
    eps_method = None
    eps_confidence = None
    if isinstance(eps_normalization, dict):
        normalized_eps = safe_float(
            eps_normalization.get("normalized_eps")
        )
        eps_method = eps_normalization.get("method")
        eps_confidence = eps_normalization.get("confidence")

    calculated_ev_to_ebitda = None
    if (
        enterprise_value is not None
        and enterprise_value > 0
        and ebitda is not None
        and ebitda > 0
    ):
        calculated_ev_to_ebitda = (
            enterprise_value / ebitda
        )

    display_ev_to_ebitda = None
    ev_to_ebitda_status = "unverified"
    ev_to_ebitda_note = None

    if calculated_ev_to_ebitda is None:
        ev_to_ebitda_note = (
            "EV/EBITDA konnte aus Enterprise Value und EBITDA nicht "
            "belastbar berechnet werden. Es wird kein Wert geschätzt."
        )
    elif (
        yahoo_ev_to_ebitda is not None
        and yahoo_ev_to_ebitda > 0
    ):
        deviation = abs(
            calculated_ev_to_ebitda
            / yahoo_ev_to_ebitda
            - 1.0
        )
        if deviation <= 0.20:
            display_ev_to_ebitda = calculated_ev_to_ebitda
            ev_to_ebitda_status = "plausible"
            ev_to_ebitda_note = (
                "EV/EBITDA-Plausibilitätscheck bestanden: Die aus "
                "Enterprise Value und EBITDA berechnete Kennzahl liegt "
                "innerhalb von 20 % des separat gemeldeten Yahoo-"
                "enterpriseToEbitda. Bei Autoherstellern bleibt dieser "
                "Wert trotzdem nur Konzern-Kontext, weil Finanzdienstleistungen "
                "die Konzernkennzahlen beeinflussen können."
            )
        else:
            ev_to_ebitda_status = "conflict"
            ev_to_ebitda_note = (
                "⚠️ EV/EBITDA nicht belastbar: Die selbst berechnete "
                "Kennzahl weicht um mehr als 20 % vom separat gemeldeten "
                "Yahoo-enterpriseToEbitda ab. Deshalb wird sie nicht als "
                "belastbare Referenz angezeigt."
            )
    else:
        ev_to_ebitda_note = (
            "EV/EBITDA konnte zwar aus Enterprise Value und EBITDA "
            "berechnet werden, aber ein separater Yahoo-Anker fehlt. "
            "Der Wert wird deshalb nicht als belastbar angezeigt."
        )

    available_anchors = sum(
        value is not None
        for value in [
            normalized_eps,
            display_ev_to_ebitda,
            operating_cashflow
        ]
    )

    readiness = (
        "Teilweise"
        if available_anchors >= 2
        else "Unvollständig"
    )

    return {
        "applicable": True,
        "normalized_eps": normalized_eps,
        "eps_method": eps_method,
        "eps_confidence": eps_confidence,
        "enterprise_value": enterprise_value,
        "ebitda": ebitda,
        "calculated_ev_to_ebitda": calculated_ev_to_ebitda,
        "display_ev_to_ebitda": display_ev_to_ebitda,
        "yahoo_ev_to_ebitda": yahoo_ev_to_ebitda,
        "ev_to_ebitda_status": ev_to_ebitda_status,
        "ev_to_ebitda_note": ev_to_ebitda_note,
        "operating_cashflow": operating_cashflow,
        "free_cashflow_reference": free_cashflow_reference,
        "total_cash_reference": total_cash_reference,
        "total_debt_reference": total_debt_reference,
        "automotive_fcf_available": False,
        "industrial_net_debt_available": False,
        "financial_services_split_available": False,
        "readiness": readiness,
        "note": (
            "Autohersteller-Sondermodell V1 bleibt ein reiner Daten- und "
            "Plausibilitätsblock. Yahoo-Free-Cashflow, Cash und Schulden "
            "werden bei Autoherstellern nicht als Automotive-Industrie-FCF "
            "oder Industrie-Netto-Schulden interpretiert, weil konsolidierte "
            "Werte häufig das Finanzdienstleistungsgeschäft enthalten. "
            "Automotive Free Cash Flow, Industrie-Netto-Cash/-Schulden und "
            "der Finanzdienstleistungs-Anteil werden nicht geschätzt. Noch "
            "keine Auto-Punkte, kein Bewertungs-Multiple und kein Fair Value."
        )
    }


# =========================================================
