def _reit_snapshot_is_fresh(snapshot):
    if not isinstance(snapshot, dict):
        return False
    try:
        valid_until = datetime.strptime(snapshot.get("valid_until"), "%d.%m.%Y").date()
        return datetime.now().date() <= valid_until
    except Exception:
        return False


def build_reit_primary_source_gate(snapshot):
    """Validate the minimum official data set needed for later REIT scoring."""
    result = {
        "available": False,
        "integration_version": REIT_PRIMARY_SOURCE_INTEGRATION_VERSION,
        "affo_q2_per_share": None,
        "affo_h1_per_share": None,
        "affo_h1_growth_pct": None,
        "ffo_q2_per_share": None,
        "ffo_h1_per_share": None,
        "normalized_ffo_h1_per_share": None,
        "affo_guidance_low": None,
        "affo_guidance_high": None,
        "affo_guidance_mid": None,
        "affo_payout_q2_pct": None,
        "net_debt_to_adjusted_ebitdare": None,
        "occupancy_pct": None,
        "same_store_rent_growth_h1_pct": None,
        "weighted_average_lease_term_years": None,
        "note": None,
    }
    if not isinstance(snapshot, dict):
        result["note"] = (
            "REIT-Primärquellen-Gate nicht verfügbar: kein verifizierter aktueller "
            "REIT-Snapshot."
        )
        return result

    affo_q2 = safe_float(snapshot.get("affo_q2_per_share"))
    affo_h1 = safe_float(snapshot.get("affo_h1_per_share"))
    affo_h1_prior = safe_float(snapshot.get("affo_h1_prior_per_share"))
    ffo_q2 = safe_float(snapshot.get("ffo_q2_per_share"))
    ffo_h1 = safe_float(snapshot.get("ffo_h1_per_share"))
    nffo_h1 = safe_float(snapshot.get("normalized_ffo_h1_per_share"))
    guide_low = safe_float(snapshot.get("affo_guidance_low"))
    guide_high = safe_float(snapshot.get("affo_guidance_high"))
    payout = safe_float(snapshot.get("affo_payout_q2_pct"))
    leverage = safe_float(snapshot.get("net_debt_to_annualized_pro_forma_adjusted_ebitdare"))
    occupancy = safe_float(snapshot.get("occupancy_pct"))
    same_store = safe_float(snapshot.get("same_store_rent_growth_h1_pct"))
    walt = safe_float(snapshot.get("weighted_average_lease_term_years"))

    required = [affo_q2, affo_h1, ffo_q2, ffo_h1, payout, leverage, occupancy, walt]
    if any(value is None or value <= 0 for value in required):
        result["note"] = (
            "REIT-Primärquellen-Gate gesperrt: mindestens eine Pflichtkomponente aus "
            "AFFO/FFO, Ausschüttungsdeckung, Belegung oder Verschuldung fehlt."
        )
        return result

    affo_h1_growth = None
    if affo_h1_prior is not None and affo_h1_prior > 0:
        affo_h1_growth = (affo_h1 / affo_h1_prior - 1.0) * 100.0

    guide_mid = None
    if guide_low is not None and guide_high is not None and guide_low > 0 and guide_high >= guide_low:
        guide_mid = (guide_low + guide_high) / 2.0

    result.update({
        "available": True,
        "affo_q2_per_share": affo_q2,
        "affo_h1_per_share": affo_h1,
        "affo_h1_growth_pct": affo_h1_growth,
        "ffo_q2_per_share": ffo_q2,
        "ffo_h1_per_share": ffo_h1,
        "normalized_ffo_h1_per_share": nffo_h1,
        "affo_guidance_low": guide_low,
        "affo_guidance_high": guide_high,
        "affo_guidance_mid": guide_mid,
        "affo_payout_q2_pct": payout,
        "net_debt_to_adjusted_ebitdare": leverage,
        "occupancy_pct": occupancy,
        "same_store_rent_growth_h1_pct": same_store,
        "weighted_average_lease_term_years": walt,
        "note": (
            "REIT-Primärquellen-Gate bestanden: aktuelles FFO/AFFO, AFFO-Ausschüttungsquote, "
            "Belegung, Restlaufzeit und Net Debt/Annualized Pro Forma Adjusted EBITDAre "
            "stammen aus den offiziellen Realty-Income-Q2/6M-2026-Unterlagen."
        ),
    })
    return result

def build_reit_quality_score(primary_gate, snapshot=None):
    """V2.20.48 REIT-only 100-point quality score from official primary data."""
    gate = primary_gate if isinstance(primary_gate, dict) else {}
    snap = snapshot if isinstance(snapshot, dict) else {}
    result = {"available": False, "score": None, "quality_level": None, "components": {}, "note": None}
    if not gate.get("available"):
        result["note"] = "REIT-Score gesperrt: Primärquellen-Gate nicht bestanden."
        return result
    growth = safe_float(gate.get("affo_h1_growth_pct"))
    payout = safe_float(gate.get("affo_payout_q2_pct"))
    leverage = safe_float(gate.get("net_debt_to_adjusted_ebitdare"))
    occupancy = safe_float(gate.get("occupancy_pct"))
    walt = safe_float(gate.get("weighted_average_lease_term_years"))
    same_store = safe_float(gate.get("same_store_rent_growth_h1_pct"))
    recapture = safe_float(snap.get("rent_recapture_q2_pct"))
    vals=[growth,payout,leverage,occupancy,walt,same_store,recapture]
    if any(v is None for v in vals):
        result["note"] = "REIT-Score gesperrt: mindestens eine Qualitätskomponente fehlt."
        return result
    gp = 20 if growth >= 6 else 18 if growth >= 4 else 15 if growth >= 2 else 10 if growth >= 0 else 0
    pp = 20 if payout <= 75 else 18 if payout <= 80 else 14 if payout <= 85 else 8 if payout <= 90 else 0
    lp = 20 if leverage <= 4.5 else 18 if leverage <= 5.0 else 14 if leverage <= 5.5 else 8 if leverage <= 6.0 else 0
    op = 15 if occupancy >= 98.5 else 13 if occupancy >= 97.5 else 10 if occupancy >= 96.0 else 5 if occupancy >= 94.0 else 0
    wp = 10 if walt >= 8 else 8 if walt >= 6 else 5 if walt >= 4 else 2
    sp = 10 if same_store >= 3 else 8 if same_store >= 2 else 5 if same_store >= 1 else 2 if same_store >= 0 else 0
    rp = 5 if recapture >= 102 else 4 if recapture >= 100 else 2 if recapture >= 95 else 0
    score=gp+pp+lp+op+wp+sp+rp
    level = "Sehr hoch" if score >= 85 else "Hoch" if score >= 75 else "Solide" if score >= 65 else "Mittel" if score >= 55 else "Schwach"
    result.update({"available": True,"score":float(score),"quality_level":level,"components":{
        "affo_growth":{"value":growth,"points":gp,"max":20},"payout":{"value":payout,"points":pp,"max":20},
        "leverage":{"value":leverage,"points":lp,"max":20},"occupancy":{"value":occupancy,"points":op,"max":15},
        "walt":{"value":walt,"points":wp,"max":10},"same_store":{"value":same_store,"points":sp,"max":10},
        "rent_recapture":{"value":recapture,"points":rp,"max":5}},
        "note":"REIT-Score verwendet ausschließlich verifizierte REIT-Primärkennzahlen; Standard-EPS, Yahoo-FCF und generischer ROE fließen nicht ein."})
    return result


def build_reit_paffo_valuation(primary_gate, reit_score, price_financial=None):
    """Score-controlled P/AFFO anchor. NAV remains locked until a verified source exists."""
    gate=primary_gate if isinstance(primary_gate,dict) else {}
    score_block=reit_score if isinstance(reit_score,dict) else {}
    result={"available":False,"target_paffo":None,"corridor_low":None,"corridor_high":None,"affo_basis":None,"fair_value_financial":None,"current_paffo":None,"note":None}
    affo=safe_float(gate.get("affo_guidance_mid")); score=safe_float(score_block.get("score")); price=safe_float(price_financial)
    if not gate.get("available") or not score_block.get("available") or affo is None or affo <= 0 or score is None:
        result["note"]="P/AFFO-Anker gesperrt: Primärdaten, REIT-Score oder AFFO-Guidance fehlen."
        return result
    if score >= 90: target=17.0
    elif score >= 80: target=16.0
    elif score >= 70: target=15.0
    elif score >= 60: target=14.0
    else: target=12.5
    low=max(10.0,target-1.0); high=target+1.0
    fv=affo*target
    current_paffo=price/affo if price is not None and price>0 else None
    result.update({"available":True,"target_paffo":target,"corridor_low":low,"corridor_high":high,"affo_basis":affo,"fair_value_financial":fv,"current_paffo":current_paffo,
        "note":"V2.20.48 nutzt den Mittelwert der offiziellen 2026-AFFO-Guidance als Ertragsbasis. Der 100-Punkte-REIT-Score steuert einen konservativen P/AFFO-Zielanker; der Zielkorridor beträgt ±1,0×. NAV bleibt bis zu einer belastbaren Primärquelle gesperrt."})
    return result


def build_reit_special_model(
    company_type,
    info,
    price,
    currency_context,
    symbol=None
):
    """
    Conservative REIT / real-estate data block.

    V2.20.48 keeps the time-bounded official primary-source gate for supported
    REITs, adds the released REIT quality score and P/AFFO anchor, and preserves
    Yahoo values only as context. FFO/AFFO are never reconstructed from net
    income, depreciation, standard FCF or operating cash flow; NAV remains locked
    until a verified primary source is available.
    """
    type_name = str(
        company_type.get("type", "")
    ).lower()

    if (
        "reit" not in type_name
        and "immobilien" not in type_name
    ):
        return {
            "applicable": False
        }

    snapshot = get_verified_reit_snapshot(symbol)
    snapshot_fresh = _reit_snapshot_is_fresh(snapshot)
    primary_gate = (
        build_reit_primary_source_gate(snapshot)
        if snapshot_fresh
        else {
            "available": False,
            "integration_version": REIT_PRIMARY_SOURCE_INTEGRATION_VERSION,
            "note": "REIT-Primärquellen-Gate gesperrt: verifizierter Snapshot ist veraltet.",
        }
    )
    primary_source_complete = bool(snapshot_fresh and primary_gate.get("available"))

    reit_score = build_reit_quality_score(primary_gate, snapshot) if primary_source_complete else {"available": False}

    quote_price = safe_float(price)
    price_financial = convert_quote_price_to_financial_share_unit(
        quote_price,
        currency_context
    )
    reit_valuation = build_reit_paffo_valuation(primary_gate, reit_score, price_financial)

    def first_direct_value(keys):
        for key in keys:
            value = safe_float(info.get(key))
            if value is not None:
                return value, key
        return None, None

    # Direct Yahoo fields only. No FFO/AFFO reconstruction.
    ffo_total, ffo_total_source = first_direct_value([
        "fundsFromOperations",
        "fundsFromOperationsTTM",
        "ffo"
    ])
    ffo_per_share, ffo_per_share_source = first_direct_value([
        "fundsFromOperationsPerShare",
        "ffoPerShare",
        "trailingFfoPerShare"
    ])
    affo_total, affo_total_source = first_direct_value([
        "adjustedFundsFromOperations",
        "adjustedFundsFromOperationsTTM",
        "affo"
    ])
    affo_per_share, affo_per_share_source = first_direct_value([
        "adjustedFundsFromOperationsPerShare",
        "affoPerShare",
        "trailingAffoPerShare"
    ])

    price_to_ffo = None
    if (
        price_financial is not None
        and price_financial > 0
        and ffo_per_share is not None
        and ffo_per_share > 0
    ):
        price_to_ffo = (
            price_financial / ffo_per_share
        )

    price_to_affo = None
    if (
        price_financial is not None
        and price_financial > 0
        and affo_per_share is not None
        and affo_per_share > 0
    ):
        price_to_affo = (
            price_financial / affo_per_share
        )

    if ffo_per_share is not None:
        ffo_note = (
            "FFO je Aktie wurde als direkt gemeldetes Yahoo-Feld erkannt. "
            "P/FFO wird daraus transparent als reine Datenreferenz berechnet; "
            "es entsteht noch keine Bewertung."
        )
    else:
        ffo_note = (
            "FFO je Aktie ist in der aktuellen Yahoo-Datenquelle nicht "
            "separat belastbar verfügbar. Es wird nicht aus Nettogewinn, "
            "Abschreibungen, Standard-FCF oder Operating Cashflow rekonstruiert."
        )

    if affo_per_share is not None:
        affo_note = (
            "AFFO je Aktie wurde als direkt gemeldetes Yahoo-Feld erkannt. "
            "P/AFFO wird daraus transparent als reine Datenreferenz berechnet; "
            "es entsteht noch keine Bewertung."
        )
    else:
        affo_note = (
            "AFFO je Aktie ist in der aktuellen Yahoo-Datenquelle nicht "
            "separat belastbar verfügbar. Es wird nicht aus FFO, Standard-FCF "
            "oder anderen Kennzahlen geschätzt."
        )

    enterprise_value = safe_float(
        info.get("enterpriseValue")
    )
    ebitda = safe_float(
        info.get("ebitda")
    )
    yahoo_ev_to_ebitda = safe_float(
        info.get("enterpriseToEbitda")
    )
    total_cash = safe_float(
        info.get("totalCash")
    )
    total_debt = safe_float(
        info.get("totalDebt")
    )

    calculated_ev_to_ebitda = None
    if (
        enterprise_value is not None
        and enterprise_value > 0
        and ebitda is not None
        and ebitda > 0
    ):
        calculated_ev_to_ebitda = (
            enterprise_value / ebitda
        )

    display_ev_to_ebitda = None
    ev_to_ebitda_status = "unverified"
    ev_to_ebitda_note = None

    if calculated_ev_to_ebitda is None:
        ev_to_ebitda_note = (
            "EV/EBITDA konnte aus Enterprise Value und EBITDA nicht "
            "belastbar berechnet werden. Es wird kein Wert geschätzt."
        )
    elif (
        yahoo_ev_to_ebitda is not None
        and yahoo_ev_to_ebitda > 0
    ):
        deviation = abs(
            calculated_ev_to_ebitda
            / yahoo_ev_to_ebitda
            - 1.0
        )

        if deviation <= 0.20:
            display_ev_to_ebitda = calculated_ev_to_ebitda
            ev_to_ebitda_status = "plausible"
            ev_to_ebitda_note = (
                "EV/EBITDA-Plausibilitätscheck bestanden: Die aus "
                "Enterprise Value und EBITDA berechnete Kennzahl liegt "
                "innerhalb von 20 % des separat gemeldeten Yahoo-"
                "enterpriseToEbitda. Bei REITs bleibt sie nur eine "
                "Verschuldungs-/Unternehmenswert-Referenz und ersetzt "
                "kein P/FFO- oder P/AFFO-Modell."
            )
        else:
            ev_to_ebitda_status = "conflict"
            ev_to_ebitda_note = (
                "⚠️ EV/EBITDA nicht belastbar: Die selbst berechnete "
                "Kennzahl weicht um mehr als 20 % vom separat gemeldeten "
                "Yahoo-enterpriseToEbitda ab. Deshalb wird sie nicht als "
                "belastbare Referenz angezeigt."
            )
    else:
        ev_to_ebitda_note = (
            "EV/EBITDA konnte zwar aus Enterprise Value und EBITDA "
            "berechnet werden, aber ein separater Yahoo-Anker fehlt. "
            "Der Wert wird deshalb nicht als belastbar angezeigt."
        )

    net_debt = None
    if (
        total_debt is not None
        and total_cash is not None
    ):
        net_debt = total_debt - total_cash

    net_debt_to_ebitda = None
    if (
        net_debt is not None
        and net_debt > 0
        and ebitda is not None
        and ebitda > 0
    ):
        net_debt_to_ebitda = (
            net_debt / ebitda
        )

    available_anchors = sum(
        value is not None
        for value in [
            ffo_total,
            ffo_per_share,
            affo_total,
            affo_per_share,
            display_ev_to_ebitda,
            net_debt_to_ebitda
        ]
    )

    if primary_source_complete:
        readiness = "Primärdaten vollständig"
    else:
        readiness = (
            "Teilweise"
            if available_anchors >= 2
            else "Unvollständig"
        )

    return {
        "applicable": True,
        "snapshot": snapshot,
        "snapshot_fresh": snapshot_fresh,
        "primary_source_complete": primary_source_complete,
        "primary_gate": primary_gate,
        "reit_score": reit_score,
        "reit_valuation": reit_valuation,
        "integration_version": REIT_PRIMARY_SOURCE_INTEGRATION_VERSION,
        "price_financial": price_financial,
        "ffo_total": ffo_total,
        "ffo_total_source": ffo_total_source,
        "ffo_per_share": ffo_per_share,
        "ffo_per_share_source": ffo_per_share_source,
        "affo_total": affo_total,
        "affo_total_source": affo_total_source,
        "affo_per_share": affo_per_share,
        "affo_per_share_source": affo_per_share_source,
        "price_to_ffo": price_to_ffo,
        "price_to_affo": price_to_affo,
        "ffo_note": ffo_note,
        "affo_note": affo_note,
        "enterprise_value": enterprise_value,
        "ebitda": ebitda,
        "calculated_ev_to_ebitda": calculated_ev_to_ebitda,
        "display_ev_to_ebitda": display_ev_to_ebitda,
        "yahoo_ev_to_ebitda": yahoo_ev_to_ebitda,
        "ev_to_ebitda_status": ev_to_ebitda_status,
        "ev_to_ebitda_note": ev_to_ebitda_note,
        "total_cash": total_cash,
        "total_debt": total_debt,
        "net_debt": net_debt,
        "net_debt_to_ebitda": net_debt_to_ebitda,
        "nav_available": False,
        "property_value_available": False,
        "readiness": readiness,
        "note": (
            "REIT-/Immobilien-Sondermodell V2.20.48 verwendet für unterstützte REITs "
            "verifizierte offizielle FFO-/AFFO-, Ausschüttungs-, Belegungs- und "
            "Verschuldungsdaten als Primärbasis. Yahoo-FFO/AFFO, EV/EBITDA und "
            "konsolidierte Netto-Schulden bleiben reine Kontext-/Plausibilitätswerte. "
            "FFO/AFFO werden nicht aus Nettogewinn, Abschreibungen, Standard-FCF oder "
            "Operating Cashflow rekonstruiert. Der eigene REIT-Score steuert den "
            "P/AFFO-Zielanker; NAV/EPRA NTA bleibt ohne belastbare Primärquelle gesperrt."
        )
    }


def build_reit_special_control(base_control, reit_model):
    """Attach the fail-closed REIT primary-source, quality-score and P/AFFO gate to step 3B."""
    control = dict(base_control or {})
    control.setdefault("router_status", control.get("status"))
    control.setdefault("router_note", control.get("note"))

    if control.get("control_key") != "reit_ffo_affo_leverage":
        return control

    model = reit_model if isinstance(reit_model, dict) else {}
    snapshot = model.get("snapshot")
    gate = model.get("primary_gate") or {}

    if not model.get("primary_source_complete"):
        control.update({
            "implemented": False,
            "released": False,
            "confidence_cap": "Niedrig",
            "step3b_status": "REIT-Primärdaten unvollständig oder veraltet",
            "overall_status": "Nicht freigegeben",
            "snapshot": snapshot,
            "checks": {"primary_gate": gate},
            "note": (
                "Die REIT-Spezialkontrolle benötigt aktuelle offizielle FFO/AFFO-, "
                "Ausschüttungs-, Belegungs- und Verschuldungsdaten. Fehlende Werte "
                "werden nicht aus Standard-EPS, Yahoo-Free-Cashflow, EBITDA oder "
                "Buchwert-Proxies geschätzt."
            ),
        })
        return control

    control.update({
        "implemented": True,
        "released": bool((model.get("reit_score") or {}).get("available") and (model.get("reit_valuation") or {}).get("available")),
        "confidence_cap": "Mittel bis Hoch",
        "step3b_status": "REIT-Score + P/AFFO-Anker freigegeben",
        "overall_status": "REIT-Bewertung freigegeben",
        "snapshot": snapshot,
        "checks": {
            "primary_gate": gate,
            "ffo_q2_per_share": gate.get("ffo_q2_per_share"),
            "ffo_h1_per_share": gate.get("ffo_h1_per_share"),
            "normalized_ffo_h1_per_share": gate.get("normalized_ffo_h1_per_share"),
            "affo_q2_per_share": gate.get("affo_q2_per_share"),
            "affo_h1_per_share": gate.get("affo_h1_per_share"),
            "affo_h1_growth_pct": gate.get("affo_h1_growth_pct"),
            "affo_guidance_low": gate.get("affo_guidance_low"),
            "affo_guidance_high": gate.get("affo_guidance_high"),
            "affo_payout_q2_pct": gate.get("affo_payout_q2_pct"),
            "net_debt_to_adjusted_ebitdare": gate.get("net_debt_to_adjusted_ebitdare"),
            "occupancy_pct": gate.get("occupancy_pct"),
            "same_store_rent_growth_h1_pct": gate.get("same_store_rent_growth_h1_pct"),
            "weighted_average_lease_term_years": gate.get("weighted_average_lease_term_years"),
            "reit_score": model.get("reit_score") or {},
            "reit_valuation": model.get("reit_valuation") or {},
        },
        "note": (
            "REIT-Schritt 3B V2.20.48 validiert die aktuelle offizielle FFO/AFFO-"
            "Ertragsbasis, AFFO-Ausschüttungsdeckung, Belegung, Restlaufzeit und "
            "Net Debt/Annualized Pro Forma Adjusted EBITDAre. Der eigene REIT-Score und "
            "P/AFFO-Anker sind freigegeben; NAV bleibt ohne belastbare Primärquelle gesperrt."
        ),
    })
    return control


